import {easyView,easyNext,ensureEasy,handleEasy} from './easy-guide.js';
import {flowGraphEditor,dependencyEditor,outputScopeEditor,impactNotice,nodeName} from './panels.js';
import {createGraph,decisionNodes,selectScope} from './structure.js';
import {RESOURCE_ACCEPT} from './resource-types.js';
import {upgradeProject,editGraph,acknowledgeGraph} from './domain.js';
import {TABS,ENTRIES,TYPES,QUESTIONS,EXAMPLES,PALETTES,COMMON_DEFAULT,GUIDE_VERSION} from './guide.js';
import {newProject,makeSample,decision,allDecisions,confirmed,sourceNames,statusNames,uid,clone,touch,updateDecision,exampleInto,addFlowExample,addConcepts,chooseConcept,applyPalette,issues,ready,nextAction,makeSnapshot,baseline,beginReview,reviewProblems,finishReview,createPlan,fileIds} from './domain.js';

const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=n=>`<img class="icon" src="/assets/icons/${n}.svg" alt="" aria-hidden="true">`;
const tag=d=>`<span class="tag ${d.status}">${statusNames[d.status]}</span>`;
const fmtDate=x=>new Date(x).toLocaleDateString('ko-KR',{month:'short',day:'numeric'});
const btn=(label,action,cls='',data='')=>`<button class="btn ${cls}" data-action="${action}" ${data}>${label}</button>`;
const arrow='<span class="arrow" aria-hidden="true">↗</span>';
let projects=[],p=null,settings={},files=[],activeRef=null,activeReview=null,activeSnapshot=null,dirty=0,saved=0,saveTimer,savePromise=null,saveError='',creationEntry='idea',modalReturn=null;
let pendingFiles=null;
const editStart=new WeakMap();
async function api(url,method='GET',data,options={}){const r=await fetch('/api'+url,{...options,method,headers:data?{'Content-Type':'application/json'}:{},...(data?{body:JSON.stringify(data)}:{})});const b=await r.json();if(!r.ok)throw new Error(b.error||'로컬 서버에 연결할 수 없습니다.');return b;}
function toast(message,error=false){const el=$('#toast');el.textContent=message;el.className='show'+(error?' error':'');clearTimeout(el.timer);el.timer=setTimeout(()=>el.className='',error?7500:3500);}
function currentTab(){return p?.progress.tab||'design';}
function changed(){dirty++;try{localStorage.setItem('atelier-draft-'+p.id,JSON.stringify(p));}catch{}setSaveState('저장 중…');clearTimeout(saveTimer);saveTimer=setTimeout(()=>flush().catch(e=>toast(e.message,true)),600);}
function setSaveState(text,error=false){const e=$('#save-state');if(e){e.textContent=text;e.classList.toggle('error',error);}}
async function flush(){clearTimeout(saveTimer);if(savePromise){await savePromise;if(saved<dirty)return flush();return;}if(!p||dirty===saved)return;const target=p,id=p.id,at=dirty,copy=clone(p);savePromise=(async()=>{try{const result=await api('/projects/'+id,'PUT',copy);if(p?.id===id){p.version=result.version;p.updatedAt=result.updatedAt;saved=at;saveError='';$('#save-error-banner')?.remove();if(dirty===at)localStorage.removeItem('atelier-draft-'+id);setSaveState('로컬에 자동 저장됨');}projects=projects.map(x=>x.id===id?{...x,name:target.name,updatedAt:result.updatedAt,version:result.version,count:target.snapshots.length}:x);}catch(e){saveError=e.message;setSaveState('저장 실패 · 입력 유지 중',true);if($('.content-shell')&&!$('#save-error-banner'))$('.content-shell').insertAdjacentHTML('afterbegin',`<div class="error-note" id="save-error-banner">입력을 유지했습니다. ${esc(e.message)} <div class="row wrap" style="margin-top:10px">${btn('다시 저장','retry-save','tiny')}${btn('현재 입력 임시 내려받기','draft-download','tiny')}${btn('최신 저장본 다시 열기','reload-latest','tiny')}</div></div>`);throw e;}finally{savePromise=null;}})();await savePromise;if(saved<dirty)return flush();}
async function refreshFiles(){if(p)files=(await api('/projects/'+p.id+'/files')).files;}
function fileURL(id){return '/api/projects/'+p.id+'/files/'+id;}
function fileExists(id){return !!files.find(f=>f.id===id&&f.exists);}
async function openProject(id){await flush();p=await api('/projects/'+id);dirty=saved=0;saveError='';activeRef=null;activeReview=null;activeSnapshot=null;await refreshFiles();settings.lastProject=id;await api('/settings','PUT',settings);const draft=localStorage.getItem('atelier-draft-'+id);render();if(draft){try{const d=JSON.parse(draft);if(d.version===p.version){showModal('저장하지 못한 입력이 있어요',`<p>현재 서버 버전과 같은 시점의 임시 입력을 찾았습니다. 복구하면 이어서 저장합니다.</p>${btn('임시 입력 복구하기','recover-draft','primary')}${btn('서버에 저장된 버전 유지','discard-draft','ghost')}`);}else toast('다른 창의 변경이 있어 임시 입력을 자동 적용하지 않았습니다. 설정에서 임시 입력을 내려받을 수 있습니다.');}catch{}}}
function getPath(obj,path){return path.split('.').reduce((a,k)=>a?.[k],obj);}
function setPath(obj,path,value){const keys=path.split('.'),last=keys.pop();const target=keys.reduce((a,k)=>a[k],obj);target[last]=value;}
function optionLabel(path,value){if(path==='entry')return ENTRIES.find(e=>e[0]===value)?.[1]||value;if(path==='settings.density')return value==='quick'?'빠른 편집':'가이드 보기';if(path.endsWith('.resolution'))return ({unverifiable:'확인 불가',resolved:'해결됨',remaining:'남아 있음','new-problem':'다른 문제 발생'})[value]||value;return value;}
function simple(label,path,{area=false,placeholder='',options=null,type='text',hint=''}={}){const value=getPath(p,path);const attrs=`data-path="${path}" aria-label="${esc(label)}"`;return `<label class="small-label">${esc(label)}</label>${options?`<select class="input small-input" ${attrs}>${options.map(x=>`<option value="${esc(x)}" ${x===value?'selected':''}>${esc(optionLabel(path,x))}</option>`).join('')}</select>`:area?`<textarea class="input small-input" ${attrs} placeholder="${esc(placeholder)}">${esc(value)}</textarea>`:`<input class="input small-input" ${attrs} type="${type}" value="${esc(value)}" placeholder="${esc(placeholder)}">`}${hint?`<small>${esc(hint)}</small>`:''}`;}
function dInput(d,prop='value',{label='',area=false,placeholder='',options=null}={}){return `${label?`<label class="small-label">${esc(label)}</label>`:''}${options?`<select class="input small-input" data-decision="${d.id}" data-prop="${prop}" aria-label="${esc(label||prop)}">${options.map(x=>`<option ${d[prop]===x?'selected':''}>${esc(x)}</option>`).join('')}</select>`:area?`<textarea class="input small-input" data-decision="${d.id}" data-prop="${prop}" aria-label="${esc(label||prop)}" placeholder="${esc(placeholder)}">${esc(d[prop])}</textarea>`:`<input class="input small-input" data-decision="${d.id}" data-prop="${prop}" aria-label="${esc(label||prop)}" value="${esc(d[prop])}" placeholder="${esc(placeholder)}">`}`;}
function statusSelect(d){return `<select class="status-select ${d.status}" data-decision="${d.id}" data-prop="status" aria-label="${esc(d.value.slice(0,30)||'항목')} 상태">${Object.entries(statusNames).map(([v,l])=>`<option value="${v}" ${d.status===v?'selected':''}>${l}</option>`).join('')}</select>`;}
function baseDecisionDetails(d){return `<details><summary>근거·출처·적용 범위 ${d.history.length?'· 변경 '+d.history.length+'회':''}</summary><div class="detail-grid"><div>${dInput(d,'reason',{label:'선택 이유와 근거',area:true,placeholder:'이 선택이 사용자 경험에 필요한 이유'})}</div><div>${dInput(d,'scope',{label:'적용 범위',placeholder:'전체 또는 특정 화면·컴포넌트'})}<label class="small-label">실제 출처를 직접 표시</label><select class="input small-input" data-decision="${d.id}" data-prop="source" aria-label="결정의 실제 출처">${Object.entries(sourceNames).map(([v,l])=>`<option value="${v}" ${d.source===v?'selected':''}>${l}</option>`).join('')}</select><small>결정 v${d.version}</small></div></div>${d.reviewNeeded?`<div class="issue">상위 결정이 바뀌었습니다. 이 항목이 여전히 맞는지 확인하세요.${btn('이 기준 다시 확인함','review-decision','tiny',`data-id="${d.id}"`)}</div>`:''}${d.history.length?`<details><summary>이전 값 보기</summary><div class="timeline">${d.history.slice(-5).reverse().map(h=>`<div><strong>v${h.version} · ${esc(statusNames[h.status])}</strong>${esc(h.value)}</div>`).join('')}</div></details>`:''}</details>`;}
function decisionDetails(d){return `<details class="decision-advanced"><summary>출처·이전 값·연결 관계 편집 (선택)</summary>${baseDecisionDetails(d)}${dependencyEditor(p,d,files)}</details>`;}
function question(q){const d=p.fields[q.key];return `<section class="field" id="field-${q.key}" data-locate="${d.id}"><div class="field-top"><label for="q-${q.key}"><span class="field-index">${q.id}</span>${q.label}${q.optional?' <small>선택</small>':''}</label>${statusSelect(d)}</div><p class="question-why">${q.why}</p><textarea id="q-${q.key}" class="input" data-decision="${d.id}" data-prop="value" data-key="${q.key}" placeholder="내 생각을 적거나, 아래 예시에서 시작해 보세요.">${esc(d.value)}</textarea><div class="field-bottom"><div class="field-actions">${q.key==='product'&&p.idea?'<button class="text-btn" data-action="use-original">원문을 이 답에 사용</button>':''}<button class="text-btn" data-action="example" data-key="${q.key}">예시 보고 고르기</button><button class="text-btn" data-action="unknown" data-key="${q.key}">아직 모르겠어요</button></div><small>출처: ${esc(sourceNames[d.source])}</small></div>${decisionDetails(d)}</section>`;}
function pageHead(tab){const t=TABS.find(t=>t[0]===tab);return `<header class="editor-head"><div class="eyebrow">${t[3]} / THE DESIGN PROCESS</div><div class="english">${t[4]}<span class="accent">.</span></div><h1>${t[5]}</h1><p>${({design:'내장 질문과 예시를 따라 의도를 구체화하세요. 자동 저장과 요구사항 확정은 별개입니다.',flow:'목표와 활동, 화면과 상태를 연결합니다. 예외에서 되돌아오는 방법도 함께 적어 주세요.',reference:'이미지를 직접 보고 관찰·해석·적용을 구분합니다. 자동 이미지 분석은 하지 않습니다.',concept:'직접 작성하거나 내장 예시를 편집해 비교하세요. 이미 정했다면 한 방향으로도 충분합니다.',style:'색 이름보다 역할을, 분위기보다 적용 위치를 정합니다. 작은 샘플로 관계를 확인해 보세요.',brief:'확정 결정의 통합 요약입니다. 프로그램은 누락과 연결을, 사용자는 의미와 적합성을 확인합니다.',prompt:'확정 결정과 버전 있는 템플릿으로 하나의 문서를 조립합니다. 실제 제작은 외부 도구에서 진행합니다.',review:'당시 기준을 고정하고 실제 결과를 비교합니다. 판정과 근거는 사용자가 직접 남깁니다.'})[tab]}</p></header>`;}
function home(){return `<header class="top-home"><a class="wordmark" href="#" data-action="home">atelier<span>.</span></a><span class="home-nav">나의 작업실</span><span class="home-status"><span class="dot"></span>내 컴퓨터에만 저장</span>${btn(icon('settings')+'설정','settings','ghost')}</header><main class="home fade-in"><section class="hero"><div><div class="eyebrow">A LITTLE STRUCTURE. A LOT OF POSSIBILITY.</div><h1>A space for<br>your next <em>idea.</em></h1><p>좋아하는 감각을, 명확한 디자인으로.<br>아이디어와 이미지에서 출발해 나만의 디자인 언어와<br>하나의 완성된 프롬프트를 만드는 작업실입니다.</p></div><div class="hero-art" id="hero-art" aria-label="색과 글자, 구성의 관계를 보여 주는 디자인 샘플"><div class="art-sheet"><small>FIND YOUR OWN</small><div class="serif">Aa</div><div class="art-line"></div><div class="art-line" style="width:63%"></div><div class="art-line" style="width:76%"></div><div style="font-size:9px;margin-top:20px;color:#8c8779">색 · 글자 · 형태 · 구성</div></div><div class="art-sheet front"><div><small>YOUR NEXT DIRECTION</small><h3 style="margin-top:24px">Less guessing.<br>More intention<span class="accent">.</span></h3></div><div><div class="art-swatches"><span style="background:#ebe8dd"></span><span style="background:#cccdbc"></span><span style="background:#464b40"></span><span style="background:#ff365d"></span></div><small style="display:block;margin-top:10px;font-size:7px">A STUDY IN BALANCE — 001</small></div></div><div class="cursor-note">your point of view</div><span class="art-caption">FROM A SPARK TO A DIRECTION</span></div></section><section class="home-section"><div class="section-heading"><div><h2>어디서 시작할까요?</h2><p>지금 가지고 있는 것부터 시작하세요. 나머지는 함께 정리할 수 있어요.</p></div><span class="eyebrow">01 — 04</span></div><div class="entry-grid">${ENTRIES.map((e,i)=>`<button class="entry-card" data-action="create" data-entry="${e[0]}"><span class="entry-number">0${i+1}</span>${arrow}<h3>${e[1]}</h3><p>${e[2]}</p></button>`).join('')}</div></section><section class="workspace-list"><div class="section-heading"><div><h2>이어서 생각하기 <small>${projects.length.toString().padStart(2,'0')}</small></h2><p>${projects.length?'마지막에 하던 작업과 다음 행동이 기다리고 있어요.':'첫 프로젝트를 만들거나, 내장 예시를 살펴보세요.'}</p></div>${btn(icon('download')+'백업 복원','restore','ghost tiny')}</div>${projects.length?`<div class="project-list">${projects.map(x=>`<button class="project-row" data-action="open" data-id="${x.id}"><div><h3>${esc(x.name)}</h3><p>${esc(x.type)} · ${TABS.find(t=>t[0]===x.progress.tab)?.[1]||'프로젝트 설계'}</p></div><span class="muted" style="font-size:11px">${x.count?'프롬프트 '+x.count+'개':'설계 작성 중'}</span><span class="muted" style="font-size:10px">${fmtDate(x.updatedAt)} 저장</span><span class="arrow">↗</span></button>`).join('')}</div>`:''}</section><div class="sample-note"><div><h3 style="font-size:12px;margin-bottom:4px">조금 막막하다면, 예시부터.</h3><p>가상의 제품 데이터입니다. 예시는 제안으로 시작하고, 직접 확인해 확정합니다.</p></div><div class="row">${btn('픽셀 생존 게임 ↗','sample','tiny', 'data-kind="game"')}${btn('공주풍 네컷 서비스 ↗','sample','tiny','data-kind="photo"')}</div></div><footer class="home-footer"><span>Built for thoughtful decisions. <span class="accent">Atelier</span></span><a href="https://streamlinehq.com" target="_blank" rel="noopener">Free icons from Streamline ↗</a><span>LOCAL FIRST · GUIDE ${GUIDE_VERSION}</span></footer></main>`;}
function sidebar(){return `<aside class="sidebar"><a class="wordmark" href="#" data-action="home">atelier<span>.</span></a><div class="workspace-switch"><div class="eyebrow">PERSONAL WORKSPACE</div><button class="project-name" data-action="switch"><span>${esc(p.name)}</span><span>⌄</span></button></div><div class="sidebar-label">YOUR DESIGN PROCESS</div><nav aria-label="프로젝트 작업 영역">${TABS.map(t=>{const used=({design:()=>confirmed(p.fields.product),flow:()=>p.flows.some(confirmed),reference:()=>p.references.some(r=>r.regions.some(confirmed)),concept:()=>p.concepts.some(c=>c.selected),style:()=>p.styles.some(confirmed),brief:()=>!!p.intent,prompt:()=>!!p.snapshots.length,review:()=>p.reviews.some(r=>r.state==='completed')})[t[0]]();return `<button class="tab ${currentTab()===t[0]?'active':''}" data-action="tab" data-tab="${t[0]}" ${currentTab()===t[0]?'aria-current="page"':''}>${icon(t[2])}<span>${t[1]}</span><span class="tab-state ${used?'used':''}" title="${used?'데이터 있음':'시작 전'}"></span><span class="tab-num">${t[3]}</span></button>`;}).join('')}</nav><div class="sidebar-bottom">${btn(icon('settings')+'작업실 설정','settings','ghost tiny')}${btn(icon('help')+'이 작업실 사용법','help','ghost tiny')}<div class="local-storage"><span class="dot"></span>LOCAL WORKSPACE<br>프로젝트와 원본 파일은 이 컴퓨터에 저장됩니다.<br><a href="https://streamlinehq.com" target="_blank" rel="noopener">Free icons from Streamline ↗</a></div></div></aside>`;}
function aside(){const next=nextAction(p);return `<aside class="aside"><div class="aside-block"><div class="eyebrow">A NOTE FOR THIS STEP</div><div class="serif">Intention before<br>decoration<span class="accent">.</span></div><p>${({design:'누구를 위한 디자인인지 알면 무엇을 크게 보여 줄지도 분명해집니다. 아직 모르는 답은 예시를 보며 골라도 괜찮아요.',flow:'화면 수보다 중요한 것은 행동의 연결입니다. 하나의 화면에서 여러 행동을 해도 괜찮습니다.',reference:'보이는 것과 느낀 것을 나누어 보세요. “연한 바탕과 진한 작은 포인트”는 관찰, “차분하다”는 해석입니다.',concept:'좋은 방향은 색만 다르지 않습니다. 무엇을 주인공으로 두는지, 어떻게 배치하고 읽히게 하는지도 비교하세요.',style:'같은 핑크도 바탕인지 선택 표시인지에 따라 역할이 다릅니다. 전체 UI와 특정 리소스의 적용 범위를 나누세요.',brief:'필드가 채워졌다고 의도가 맞는 것은 아닙니다. 고객·경험·스타일의 연결은 직접 판단해 주세요.',prompt:'이 문서와 실제 참고 파일을 외부 도구에 함께 전달하세요. 내보내기는 실제 디자인 검토의 완료가 아닙니다.',review:'보기 좋은가와 목적에 맞는가는 다른 질문입니다. 스크린샷에서 알 수 없는 동작은 확인 불가로 남겨 주세요.'})[currentTab()]}</p></div><div class="aside-block"><div class="eyebrow">DECISION NOTES</div><ul><li>직접 작성과 내장 예시를 구분합니다.</li><li>자동 저장은 확정이 아닙니다.</li><li>확정한 내용만 요구로 전달합니다.</li></ul><div class="mini-stat"><span>확정 결정</span><b>${allDecisions(p).filter(confirmed).length}</b></div><div class="mini-stat"><span>프로젝트 첨부 파일</span><b>${files.length}</b></div><div class="mini-stat"><span>프롬프트 버전</span><b>${p.snapshots.length}</b></div></div><div class="aside-block"><div class="eyebrow">NEXT IN YOUR PROCESS</div><p style="margin-top:10px">${esc(next.why)}</p><button class="text-btn" style="margin-top:12px;text-align:left" data-action="navigate-next">${esc(next.label)} ↗</button></div><details><summary>최근 변경</summary><div class="timeline">${p.activity.slice(0,5).map(a=>`<div><strong>${esc(a.reason)}</strong>${fmtDate(a.at)} · 기준 r${a.revision||p.revision}</div>`).join('')||'<small>첫 결정을 기록해 보세요.</small>'}</div></details></aside>`;}
function projectNext(){return p.settings.density==='quick'||p.handoff?.waiting||p.reviews.length?nextAction(p):easyNext(p);}
function workspaceView(tab){if(p.settings.density!=='quick'){const view=easyView(p,tab,{files});if(view)return view;if(tab==='review'&&!p.reviews.length&&!p.snapshots.length)return easyReviewStart();}return ({design:designView,flow:flowView,reference:referenceView,concept:conceptView,style:styleView,brief:briefView,prompt:promptView,review:reviewView})[tab]();}
function easyReviewStart(){ensureEasy(p);return '<div class="easy-guide"><h2>기존 화면에서 바꾸고 싶은 점부터 시작해요.</h2><p class="easy-intro">새 프로젝트의 모든 질문을 채울 필요 없어요. 기대한 모습과 실제 결과를 먼저 비교합니다.</p><label class="easy-label" for="review-wanted">원래 어떤 화면이나 동작을 원했나요?</label><textarea class="input" id="review-wanted" data-path="progress.easy.reviewWanted" placeholder="예: 현재 장비 상태와 조작 결과를 한눈에 보고 싶어요.">'+esc(p.progress.easy.reviewWanted||p.idea)+'</textarea><label class="easy-label" for="review-problem">지금 무엇이 불편해서 바꾸고 싶나요?</label><textarea class="input" id="review-problem" data-path="progress.easy.reviewProblem" placeholder="예: 켜짐과 꺼짐이 색으로만 표시돼 구별하기 어려워요.">'+esc(p.progress.easy.reviewProblem||'')+'</textarea><p class="easy-hint">다음 화면에서 실제 이미지 또는 직접 실행한 기록을 등록합니다. 없는 결과를 만들어 넣지 않습니다.</p><button class="btn primary" data-action="easy-start-review">이 기대와 실제 결과 비교하기 →</button></div>';}
function workspace(){const next=projectNext(),tab=currentTab();return `<div class="layout ${p.settings.density==='quick'?'':'guided-layout'}"><div>${sidebar()}</div><div class="workspace-main"><header class="workspace-top"><button class="mobile-menu" data-action="mobile-menu" aria-label="메뉴 열기">☰</button><div class="breadcrumbs"><span>나의 작업실</span><span>/</span><strong>${esc(p.name)}</strong></div><div class="save-state ${saveError?'error':''}" id="save-state">${saveError?'저장 실패 · 입력 유지 중':'로컬에 자동 저장됨'}</div><div class="view-toggle" aria-label="편집 밀도"><button data-action="density" data-value="guide" class="${p.settings.density==='guide'?'active':''}">가이드 보기</button><button data-action="density" data-value="quick" class="${p.settings.density==='quick'?'active':''}">상세 편집</button></div><div class="toolbar">${btn(icon('download')+'백업','backup','ghost tiny')}</div></header><main class="content-shell">${saveError?`<div class="error-note" id="save-error-banner">${esc(saveError)} ${btn('다시 저장','retry-save','tiny')}${btn('현재 입력 임시 내려받기','draft-download','tiny')}</div>`:''}${p.progress.returnTo?`<div class="learning-note row between"><span>이 작업을 보완한 뒤 이전 흐름으로 돌아갈 수 있습니다.</span>${btn('원래 작업으로 돌아가기','return','tiny')}</div>`:''}<section class="next-banner"><div><div class="eyebrow"><span class="dot pink"></span>${p.handoff?'WAITING FOR YOUR RESULT':'YOUR NEXT SMALL STEP'}</div><h3>${esc(next.label)}</h3><p>${esc(next.why)}</p></div>${btn(esc(next.label)+' <span class="arrow">→</span>','navigate-next','primary')}</section><div class="editor-grid"><div class="editor fade-in ${p.settings.density==='quick'?'quick':'guided-editor'}">${pageHead(tab)}${workspaceView(tab)}</div>${aside()}</div></main></div></div>`;}
function render(){if(p)upgradeProject(p);const y=window.scrollY;$('#app').innerHTML=p?workspace():home();if(p&&dirty>saved)setSaveState(saveError?'저장 실패 · 입력 유지 중':'저장 중…',!!saveError);bindReference();bindHero();bindEnhancedPanels();window.scrollTo(0,y);}
function bindEnhancedPanels(){if(!p)return;if(currentTab()==='flow'&&p.settings.density==='quick')for(const f of p.flows){const el=$$('[data-locate]').find(el=>el.dataset.locate===f.id);if(el)el.insertAdjacentHTML('beforeend',flowGraphEditor(p,f));}const notice=impactNotice(p);if(notice)$('.editor-head')?.insertAdjacentHTML('afterend',notice);if(currentTab()==='review'){const r=p.reviews.find(r=>r.id===activeReview)||p.reviews.at(-1);if(r?.recheck?.criterionIds.length)$('.comparison')?.insertAdjacentHTML('beforebegin',`<div class="issue"><span>원본 결정 변경으로 ${r.recheck.criterionIds.length}개 기준의 새 검토가 필요합니다. 이전 판정과 근거는 당시 기록으로 보존했습니다.</span>${btn('변경 이유와 새 기준 등록','baseline','tiny')}</div>`);}loadProjectFonts();}
function renderTop(){render();window.scrollTo({top:0,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});}
function footer(next,label,reason){return `<div class="editor-footer"><p>${reason}</p>${btn(label+' <span class="arrow">→</span>','tab','primary',`data-tab="${next}"`)}</div>`;}

function designView(){const stage=p.progress.guideStage||0;const groups=['제품과 사용자','고객과 가치','환경과 범위','표현과 검토'];const quick=p.settings.density==='quick';return `<div class="learning-note"><strong>입력 원문</strong><p style="margin-top:6px;white-space:pre-wrap">${esc(p.idea||'등록한 아이디어 문장이 없습니다. 아래 질문에서 시작할 수 있습니다.')}</p><button class="text-btn" data-action="edit-idea" style="margin-top:8px">원문 직접 수정하기</button></div><div class="section-title"><h2>어떤 제품을 만드나요?</h2><small>유형에 맞는 질문과 예시</small></div><div class="type-row">${TYPES.map(t=>`<button class="chip ${p.type===t?'selected':''}" data-action="type" data-value="${t}">${t}</button>`).join('')}</div>${quick?'':`<div class="guide-tabs">${groups.map((g,i)=>`<button class="${i===stage?'active':''}" data-action="guide-stage" data-value="${i}">${String(i+1).padStart(2,'0')} ${g}</button>`).join('')}</div>`}${QUESTIONS.filter(q=>quick||q.group===stage).map(question).join('')}${!quick?`<div class="row between"><small>한 번에 세 가지씩. 다른 항목도 언제든 편집할 수 있어요.</small>${btn(stage<3?'다음 질문 세 가지 보기 →':'기능과 콘텐츠 이어서 정리하기 ↓','guide-next','tiny')}</div>`:''}${quick||stage===3?designLists():`<details style="margin-top:26px"><summary>기능 범위와 콘텐츠 준비도 편집하기</summary>${designLists()}</details>`}${footer('flow','목표를 사용자 흐름으로 연결하기','사용자가 목표에 이르는 행동과 화면을 연결합니다.')}`;}
function designLists(){return `<div class="section-title"><h2>기능과 범위</h2><div class="row">${btn('유형별 예시 복제','feature-example','tiny')}${btn('+ 기능 추가','add-feature','tiny')}</div></div>${p.features.map((d,i)=>`<article class="item" data-locate="${d.id}"><div class="item-title"><strong>기능 ${i+1}</strong>${statusSelect(d)}</div>${dInput(d,'value',{label:'기능 이름'})}<div class="detail-grid"><div>${dInput(d,'purpose',{label:'목적'})}${dInput(d,'action',{label:'사용자 행동'})}</div><div>${dInput(d,'priority',{label:'우선순위',options:['이번 범위','후속 범위','미정']})}${dInput(d,'info',{label:'필요한 정보'})}</div></div><label class="small-label">연결할 흐름</label><div class="screen-checks">${p.flows.map(f=>`<label><input type="checkbox" data-action="feature-link" data-id="${d.id}" value="${f.id}" ${d.flowIds?.includes(f.id)?'checked':''}>${esc(f.value)}</label>`).join('')||'<small>흐름 탭에서 만든 흐름을 여기에 연결할 수 있습니다.</small>'}</div>${decisionDetails(d)}</article>`).join('')||empty('Start with the essentials.','이번에 필요한 핵심 기능부터 한 가지씩 기록해 보세요.','기능 추가하기','add-feature')}<div class="section-title"><h2>콘텐츠와 자료 준비</h2>${btn('+ 자료 계획 추가','add-content','tiny')}</div>${p.contents.map((d,i)=>`<article class="item" data-locate="${d.id}"><div class="item-title"><strong>자료 ${i+1}</strong>${statusSelect(d)}</div>${dInput(d,'value',{label:'자료 이름'})}<div class="detail-grid"><div>${dInput(d,'kind',{label:'종류',options:['문구','사진','제품 화면','일러스트','게임 에셋','아이콘','데이터']})}${dInput(d,'availability',{label:'확보 상태',options:['보유','제작 필요','제공 예정','미정']})}${dInput(d,'materialType',{label:'표시 상태',options:['실제 자료','임시 샘플','제안 문구']})}</div><div>${dInput(d,'purpose',{label:'용도와 사용할 화면'})}${dInput(d,'conditions',{label:'크기·형식 등 제작 조건'})}</div></div>${dInput(d,'content',{label:'실제 내용 또는 제작할 내용',area:true})}${d.fileId?fileBlock(d.fileId):''}<label class="small-label">실제 문서·이미지·데이터 파일 등록 (선택)</label><input type="file" accept="${RESOURCE_ACCEPT}" data-upload="content" data-id="${d.id}" aria-label="콘텐츠 파일 등록">${decisionDetails(d)}</article>`).join('')||'<div class="learning-note">실제 자료가 없어도 제작 계획을 남겨 진행할 수 있습니다. 임시 샘플을 실제 고객 자료로 표시하지 않습니다.</div>'}`;}
function empty(en,text,label,action,data=''){return `<div class="empty"><div class="serif">${en}</div><p>${text}</p>${btn(label,action,'tiny',data)}</div>`;}
function flowView(){return `<div class="learning-note"><strong>전체 목표</strong> ${esc(p.fields.goal.value||'프로젝트 설계에서 목표를 작성해 주세요.')}<br>${p.type==='게임'?'게임에서는 반복 루프와 플레이 상태가 중심입니다. 구매나 결제를 필수로 넣지 않습니다.':'전체 완료 흐름과 이전 단계 복구를 함께 연결하세요. 화면 하나가 여러 흐름에 연결되어도 됩니다.'}</div><div class="section-title"><h2>활동과 흐름</h2><div class="row">${btn('내장 흐름 예시 복제','flow-example','tiny')}${btn('+ 흐름','add-flow','tiny')}${btn('+ 화면·상태','add-screen','tiny')}</div></div>${p.flows.map((f,i)=>`<article class="item" data-locate="${f.id}"><div class="item-title"><strong>FLOW ${i+1}</strong>${statusSelect(f)}</div>${dInput(f,'value',{label:'흐름 이름'})}<div class="detail-grid"><div>${dInput(f,'goal',{label:'연결된 전체 목표'})}${dInput(f,'role',{label:'사용자 역할'})}</div><div>${dInput(f,'start',{label:'시작 조건'})}${dInput(f,'complete',{label:'완료 조건'})}</div></div><div class="flow-map">${f.steps.map((id,j)=>{const s=p.screens.find(x=>x.id===id);return `${j?'<span class="flow-join">→</span>':''}<button class="flow-node ${s?.status==='confirmed'?'selected':''}" data-action="locate" data-tab="flow" data-id="${id}"><small>0${j+1} · ${s?.kind||'참조 없음'}</small>${esc(s?.value||'누락된 화면')}</button>`;}).join('')}${f.loop?'<span class="flow-join">↩</span>':''}</div><label class="small-label">흐름에 화면 연결 · 선택한 순서대로 배치됩니다</label><div class="screen-checks">${p.screens.map(s=>`<label><input type="checkbox" data-action="flow-screen" data-id="${f.id}" value="${s.id}" ${f.steps.includes(s.id)?'checked':''}>${esc(s.value)}</label>`).join('')}</div><div class="detail-grid"><div>${dInput(f,'branch',{label:'분기와 되돌아가기',area:true})}</div><div>${dInput(f,'recovery',{label:'실패와 복구',area:true})}</div></div><label class="small-label"><input type="checkbox" data-decision="${f.id}" data-prop="loop" ${f.loop?'checked':''}> 마지막에서 처음으로 반복되는 흐름</label>${decisionDetails(f)}</article>`).join('')||empty('Every step has a purpose.','직접 연결하거나 제품 유형에 맞는 내장 예시를 복제해 수정하세요.','내장 흐름 예시 보기','flow-example')}<div class="section-title"><h2>화면과 상태의 역할</h2><small>이미지에서 보이지 않는 기능은 추가 설계입니다.</small></div>${p.screens.map((s,i)=>`<details class="item" data-locate="${s.id}"><summary><span class="row between"><strong>${String(i+1).padStart(2,'0')} ${esc(s.value)}</strong>${tag(s)}</span></summary><div class="item-title"><strong>화면·패널·모드</strong>${statusSelect(s)}</div><div class="detail-grid"><div>${dInput(s,'value',{label:'이름'})}${dInput(s,'kind',{label:'종류',options:['페이지','패널','모달','게임 상태','모드']})}${dInput(s,'role',{label:'전체 경험에서의 역할'})}${dInput(s,'entry',{label:'진입 조건'})}${dInput(s,'priority',{label:'먼저 볼 정보와 보조 정보'})}</div><div>${dInput(s,'actions',{label:'가능한 행동들'})}${dInput(s,'response',{label:'시스템 반응과 데이터 변화'})}${dInput(s,'next',{label:'다음·이전·반복 연결'})}${dInput(s,'exceptions',{label:'빈 상태·실패·권한·취소'})}${dInput(s,'preserve',{label:'복구 시 보존할 데이터'})}</div></div>${decisionDetails(s)}</details>`).join('')}${footer('reference','레퍼런스에서 표현의 단서 찾기','이미지가 없어도 직접 관찰한 취향과 스타일로 진행할 수 있습니다.')}`;}
function fileBlock(id){const f=files.find(f=>f.id===id);if(!f?.exists)return '<div class="error-note">참조 파일이 없습니다. 원본을 다시 등록해 주세요.</div>';const image=['image/png','image/jpeg','image/webp'].includes(f.mime);return `<div class="file-preview">${image?`<img class="ref-image" src="${fileURL(id)}" alt="${esc(f.name)}">`:''}<div><strong>실제 파일 · ${esc(f.name)}</strong><p>${esc(f.mime)} · ${(f.size/1024).toFixed(0)} KB · SHA-256 보존</p>${btn('이 원본 파일 내려받기','download-file','tiny',`data-id="${id}"`)}</div>${f.mime.startsWith('font/')?`<div class="font-file-sample" data-font-file="${id}">한글과 English, 숫자 0123456789<br>좋아하는 감각을 명확한 기준으로.</div>`:''}</div>`;}
function referenceView(){const r=p.references.find(r=>r.id===activeRef)||p.references[0];if(r)activeRef=r.id;return `<div class="row wrap" style="margin-bottom:20px">${btn(icon('image')+'원본 이미지 등록','upload-reference','tiny')}${btn('+ 출처 URL과 메모','add-reference-url','tiny')}${p.references.length?`<select class="input small-input" id="ref-select" aria-label="작업할 레퍼런스" style="width:auto;max-width:250px">${p.references.map(x=>`<option value="${x.id}" ${x.id===r.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select>`:''}</div>${!r?`<div class="upload"><label><div class="serif">A detail worth noticing.</div><p>좋아하는 이미지 한 장이면 충분해요. 원본은 로컬에 보관됩니다.<br>PNG · JPEG · WebP / 파일당 15MB</p><input type="file" accept="image/png,image/jpeg,image/webp" data-upload="reference" aria-label="레퍼런스 원본 이미지"></label></div><div class="learning-note" style="margin-top:20px">이미지가 없다면 컨셉과 스타일을 직접 작성해도 됩니다. URL만 등록하면 출처로 보관하며 이미지를 관찰했다고 표시하지 않습니다.</div>`:`<article class="item"><div class="row between"><h2 style="font-size:15px">${esc(r.name)}</h2><small>REFERENCE ${p.references.indexOf(r)+1}</small></div><div class="detail-grid" style="margin:12px 0"><div>${simple('이름',`references.${p.references.indexOf(r)}.name`)}${simple('출처 URL',`references.${p.references.indexOf(r)}.url`)}</div><div>${simple('등록 역할',`references.${p.references.indexOf(r)}.role`,{options:['좋아하는 전체 느낌','특정 소재','피하고 싶은 예시','실제 에셋 후보']})}${simple('취향 메모',`references.${p.references.indexOf(r)}.note`)}</div></div>${r.fileId&&fileExists(r.fileId)?`<p class="question-why">이미지에서 드래그해 사각 영역을 지정하세요. 좌표는 원본의 비율로 저장합니다.</p><div class="reference-stage" id="reference-stage" data-id="${r.id}"><img src="${fileURL(r.fileId)}" alt="${esc(r.name)} 원본" id="reference-original">${r.regions.map((a,i)=>`<div class="region-box" style="display:${a.fileId&&a.fileId!==r.fileId?'none':'block'};left:${a.rect.x*100}%;top:${a.rect.y*100}%;width:${a.rect.w*100}%;height:${a.rect.h*100}%"><span>A${i+1}</span></div>`).join('')}</div><div class="row wrap">${btn('전체 이미지 영역으로 기록하기','whole-region','tiny',`data-id="${r.id}"`)}${btn('원본 교체하기','replace-reference','tiny',`data-id="${r.id}"`)}</div>`:`<div class="error-note">${r.fileId?'원본 파일을 찾을 수 없습니다.':'출처 URL만 등록되어 있습니다.'} 실제 이미지를 등록하거나 취향을 직접 작성해 주세요.</div><input type="file" accept="image/png,image/jpeg,image/webp" data-upload="replace-reference" data-id="${r.id}" aria-label="누락된 레퍼런스 원본 등록">`}</article><div class="section-title"><h2>관찰에서 적용으로</h2><small>내장 문장은 관찰을 돕는 일반 예시입니다.</small></div>${r.regions.map((a,i)=>`<article class="item" data-locate="${a.id}"><div class="item-title"><strong>A${i+1} · 선택 영역</strong>${statusSelect(a)}</div>${a.fileId&&a.fileId!==r.fileId?`<div class="issue">이전 원본의 영역과 크롭입니다. 새 원본으로 다시 확인해야 합니다.${btn('현재 원본에서 같은 영역 재크롭','recrop-region','tiny',`data-id="${a.id}" data-ref="${r.id}"`)}</div>`:''}<div class="ref-thumb-row">${a.cropId&&fileExists(a.cropId)?`<img src="${fileURL(a.cropId)}" alt="A${i+1} 크롭">`:'<small>크롭 파일 없음 · 원본에서 좌표 확인</small>'}<div><small>${a.id}<br>x ${a.rect.x.toFixed(3)} · y ${a.rect.y.toFixed(3)} · w ${a.rect.w.toFixed(3)} · h ${a.rect.h.toFixed(3)}</small><p>관찰할 대상과 실제 적용 대상을 연결하세요.</p></div></div><div class="detail-grid" style="margin-top:16px"><div>${dInput(a,'dimension',{label:'무엇을 참고하나요?',options:['색 관계','형태','재질','글자 표현','구성','밀도','이미지 언어','인터랙션 아이디어']})}${dInput(a,'observation',{label:'관찰 · 실제로 보이는 특징',area:true,placeholder:'예: 넓은 연한 바탕과 작은 진한 포인트'})}</div><div>${dInput(a,'interpretation',{label:'해석 · 왜 좋은가요?',area:true,placeholder:'예: 차분하지만 행동 위치가 분명하게 느껴짐'})}${dInput(a,'target',{label:'적용할 화면·컴포넌트·리소스',placeholder:'예: 상태 표시 패널과 주요 버튼에만'})}</div></div>${dInput(a,'purpose',{label:'제품 목적과 연결하는 이유'})}<div class="detail-grid"><div>${dInput(a,'keep',{label:'유지할 특징'})}${dInput(a,'change',{label:'프로젝트에 맞게 바꿀 특징'})}</div><div>${dInput(a,'avoid',{label:'참고하지 않을 요소'})}${dInput(a,'useMode',{label:'사용 방식',options:['시각 원리 참고','실제 파일 사용 · 조건 확인 필요']})}</div></div><div class="row" style="margin-top:12px">${btn('관찰 문장 예시 보기','observation-help','tiny',`data-id="${a.id}"`)}<button class="text-btn" data-action="sync-observation" data-id="${a.id}">이 관찰로 적용 문장 갱신</button></div><div class="learning-note" style="margin-top:13px"><strong>적용 문장</strong><p>${esc(a.observation||'[관찰 특징]')}을 ${esc(a.purpose||'[제품 목적]')}을 위해 ${esc(a.target||'[적용 대상]')}에 사용합니다. ${esc(a.keep||'[유지 관계]')}은 유지하고 ${esc(a.change||'[조정 요소]')}는 바꿉니다.</p></div>${decisionDetails(a)}</article>`).join('')}${!r.regions.length?'<div class="learning-note">원본의 전체 느낌 또는 특정 부분을 선택해 첫 관찰을 기록하세요.</div>':''}`}${footer('concept','정리한 특징으로 방향 비교하기','관찰한 사실을 보며 컨셉을 직접 작성하거나 내장 예시를 편집합니다.')}`;}
function preview(c){return `<div class="concept-preview" style="--sample-bg:${esc(c.bg)};--sample-text:${esc(c.text)};--sample-accent:${esc(c.accent)};--sample-font:${['serif','sans-serif','monospace'].includes(c.font)?c.font:'sans-serif'};--sample-radius:${esc(c.shape)}"><span class="eyebrow">LOCAL CONCEPT SAMPLE</span><h3>${esc(p.name)}</h3><p>${esc(p.fields.goal.value||'핵심 콘텐츠를 보고 필요한 작업을 시작하세요.')}</p><span class="sample-button">${esc(p.screens[0]?.value||'작업 시작하기')}</span></div>`;}
function conceptView(){return `<div class="learning-note"><strong>${p.entry==='concept'?'이미 정한 방향이 있군요.':'서로 다른 표현을 비교해 보세요.'}</strong> ${p.entry==='concept'?'한 방향만 등록하고 색·서체·형태와 적용 범위를 구체화하면 됩니다.':'색뿐 아니라 주인공·글자·구성·재질 중 두 가지 이상에서 차이를 적어 보세요.'}</div><div class="section-title"><h2>${p.entry==='concept'?'내가 정한 컨셉':'방향 비교'}</h2><div class="row">${btn('+ 직접 컨셉 작성','add-concept','tiny')}${btn('내장 두 방향 복제','concept-examples','tiny')}</div></div>${p.concepts.length?`<div class="concept-grid">${p.concepts.map((c,i)=>`<article class="concept-card ${c.selected?'chosen':''}" data-locate="${c.id}">${preview(c)}<div class="concept-body"><div class="row between"><span class="eyebrow">DIRECTION ${String(i+1).padStart(2,'0')}</span>${statusSelect(c)}</div>${dInput(c,'value',{label:'컨셉 이름'})}${dInput(c,'summary',{label:'핵심 문장',area:true})}<details><summary>같은 항목으로 비교·직접 편집하기</summary>${[['experience','사용자에게 전달할 경험'],['hero','가장 크게 보여 줄 대상'],['typography','글자의 역할과 위계'],['material','이미지와 재질'],['layout','구성과 정보 밀도'],['intensity','화면별 적용 강도'],['resources','필요한 리소스와 제작 부담'],['reference','원본에서 유지·조정한 부분'],['assumptions','확인할 가정']].map(([k,l])=>`<div class="concept-detail">${dInput(c,k,{label:l,area:true})}</div>`).join('')}<div class="detail-grid"><div>${dInput(c,'bg',{label:'배경 색 #RRGGBB'})}${dInput(c,'text',{label:'본문 색 #RRGGBB'})}</div><div>${dInput(c,'accent',{label:'강조 색 #RRGGBB'})}${dInput(c,'font',{label:'샘플 제목 서체',options:['serif','sans-serif','monospace']})}</div></div></details>${dInput(c,'reason',{label:'이 방향이 내 의도에 맞는 이유'})}<p style="margin:12px 0">출처: ${sourceNames[c.source]} · 비교용 샘플이며 완성 UI가 아닙니다.</p><div class="row wrap">${btn(c.selected?'선택한 방향 ✓':'이 방향을 선택하기','choose-concept',c.selected?'tiny':'primary tiny',`data-id="${c.id}"`)}${btn('이 요소로 새 조합','mix-concept','tiny',`data-id="${c.id}"`)}</div></div></article>`).join('')}</div>`:empty('One idea, many expressions.','이미 정한 컨셉을 등록하거나, 직접 편집할 두 가지 내장 예시에서 시작하세요.','이미 정한 컨셉 등록','add-concept')}<div class="row wrap" style="margin-top:20px">${btn('둘 다 맞지 않아요 · 이유 기록','concept-neither','ghost tiny')}${btn('아직 모름 · 팔레트와 구성 비교','tab','ghost tiny','data-tab="style"')}</div>${footer('style','이 방향으로 색과 서체 비교하기','선택한 컨셉을 실제 색·한글·컴포넌트 조합에서 확인합니다.')}`;}
function styleView(){const c=p.concepts.find(c=>c.selected)||p.concepts[0];const get=(role,fallback)=>p.styles.find(s=>s.role===role&&confirmed(s))?.value||fallback;const sample={bg:get('배경',c?.bg||'#f3f2ee'),text:get('본문',c?.text||'#30342e'),accent:get('강조',c?.accent||'#516b50'),font:c?.font||'sans-serif',shape:get('형태',c?.shape||'8px')};return `<div class="section-title" style="margin-top:0"><h2>역할이 있는 팔레트 비교</h2><small>이미지 분석 결과가 아닌 내장 조합</small></div><div class="palette-options">${PALETTES.map((a,i)=>`<button class="palette-option" data-action="palette" data-index="${i}"><h3>${a.label}</h3><div class="swatch-row">${[a.bg,a.text,a.accent].map((v,j)=>`<span class="swatch" style="background:${v};color:${j>0?'#fff':'#333'}">${['배경','본문','강조'][j]}</span>`).join('')}</div><p>${a.layout}</p></button>`).join('')}</div><div class="style-sample" style="--sample-bg:${esc(sample.bg)};--sample-text:${esc(sample.text)};--sample-accent:${esc(sample.accent)};--sample-radius:${esc(sample.shape)}"><span class="eyebrow" style="color:inherit;opacity:.6">YOUR CURRENT COMBINATION · 확정 규칙 기준</span><div class="serif" style="margin-top:12px">Small details. Clear intention.</div><h3>좋아하는 감각을, 나만의 기준으로.</h3><p>긴 한글 문장도 편하게 읽을 수 있어야 합니다. 중요한 내용과 보조 정보를 구분하고, 선택한 상태를 글자로도 알려 주세요.</p><div class="row wrap"><span class="sample-button">선택한 방향으로 계속하기</span><span style="font-size:10px;padding:6px 12px;border:1px solid currentColor;border-radius:${esc(sample.shape)}">선택됨 ✓</span><button class="btn tiny" disabled>준비 중 · 사용 불가</button></div><div class="error-note" style="margin:16px 0 0">오류 예시 · 입력을 유지했습니다. 다시 시도할 수 있습니다.</div></div><div class="section-title"><h2>스타일 규칙</h2><div class="row">${c?btn('선택 컨셉의 규칙 복제','concept-styles','tiny'):''}${btn('+ 규칙 직접 추가','add-style','tiny')}</div></div>${p.styles.map((s,i)=>`<article class="item" data-locate="${s.id}"><div class="item-title"><strong>RULE ${String(i+1).padStart(2,'0')}</strong>${statusSelect(s)}</div><div class="detail-grid"><div>${dInput(s,'role',{label:'역할',options:['배경','본문','강조','서체','형태','배치','재질','모션','선택','오류','기타']})}${dInput(s,'value',{label:'명시적 값 또는 표현 규칙',area:!['배경','본문','강조'].includes(s.role)})}</div><div>${dInput(s,'scope',{label:'어디에 적용하나요?'})}${dInput(s,'exception',{label:'예외와 조정 가능한 조건'})}</div></div>${decisionDetails(s)}</article>`).join('')||'<div class="learning-note">조합을 고르면 제안 상태의 규칙으로 복제됩니다. 직접 수정하고 항목별로 확정해 주세요.</div>'}<div class="section-title"><h2>리소스 제작 계획</h2>${btn('+ 리소스 계획','add-asset','tiny')}</div><div class="learning-note">${p.type==='게임'?'타일 규격·캐릭터 비율·외곽선·명암·애니메이션 기준을 기록하세요.':p.type==='제작 도구'?'원본 자료·편집 리소스·출력 파일과 미리보기의 관계를 기록하세요.':'실제 콘텐츠·원본 이미지·서체·규격과 출처·파일 사용 조건을 기록하세요.'} 보유 파일과 제작이 필요한 자료를 구분합니다.</div>${p.assets.map((a,i)=>`<article class="item" data-locate="${a.id}" style="margin-top:15px"><div class="item-title"><strong>ASSET ${i+1}</strong>${statusSelect(a)}</div>${dInput(a,'value',{label:'리소스 이름'})}<div class="detail-grid"><div>${dInput(a,'kind',{label:'종류'})}${dInput(a,'purpose',{label:'사용할 화면과 용도'})}${dInput(a,'method',{label:'제작 방식',options:['기존 파일','직접 제작','구매 검토','생성 요청']})}${dInput(a,'availability',{label:'확보 상태',options:['보유','제작 필요','확인 필요']})}</div><div>${dInput(a,'rules',{label:'크기·비율·재질·팔레트 기준',area:true})}${dInput(a,'sourceUrl',{label:'출처 URL'})}${dInput(a,'usage',{label:'실제 사용 조건'})}${dInput(a,'review',{label:'확인 방법'})}</div></div>${a.fileId?fileBlock(a.fileId):''}<label class="small-label">실제 보유 파일 등록 · 서체/문서/SVG/ZIP 등 (선택)</label><input type="file" accept="${RESOURCE_ACCEPT}" data-upload="asset" data-id="${a.id}" aria-label="리소스 실제 파일 등록">${decisionDetails(a)}</article>`).join('')}${footer('brief','화면별 적용과 의도 함께 점검하기','누락·참조·명시적 충돌을 확인하고 전체 설계를 읽어 봅니다.')}`;}
function issueCards(list){return list.map(i=>`<div class="issue"><span>${esc(i.message)}</span>${btn('해당 결정 보완 ↗','remedy','tiny',`data-tab="${i.tab}" data-id="${esc(i.id||'')}"`)}</div>`).join('');}
function briefView(){const list=issues(p,new Set(files.filter(f=>f.exists).map(f=>f.id)));return `<div class="row between" style="margin-bottom:17px"><span class="tag ${ready(p)?'confirmed':'proposed'}">${ready(p)?'최종 프롬프트 준비 완료':list.length?'설계 초안 가능 · 보완 필요':'사용자 의도 확인 필요'}</span><small>규칙 점검 ${list.length}건 · 디자인 품질 점수 아님</small></div><section class="brief-summary"><h3>${esc(p.name)}<span class="accent">.</span></h3><dl>${QUESTIONS.map(q=>`<div class="brief-line"><dt>${q.label}</dt><dd>${esc(p.fields[q.key].value||'아직 미정')} <span class="tag ${p.fields[q.key].status}">${statusNames[p.fields[q.key].status]}</span></dd></div>`).join('')}<div class="brief-line"><dt>확정 흐름</dt><dd>${p.flows.filter(confirmed).map(f=>esc(f.value)+' → '+f.steps.map(id=>esc(p.screens.find(s=>s.id===id)?.value||'참조 없음')).join(' → ')).join('<br>')||'아직 없음'}</dd></div><div class="brief-line"><dt>선택 방향</dt><dd>${esc(p.concepts.find(c=>c.selected)?.value||'직접 작성한 스타일 규칙 사용')}</dd></div><div class="brief-line"><dt>확정 표현 규칙</dt><dd>${p.styles.filter(confirmed).map(s=>`${esc(s.role)}: ${esc(s.value)} → ${esc(s.scope)}`).join('<br>')||'아직 없음'}</dd></div></dl></section><div class="section-title"><h2>프로그램의 규칙 점검</h2>${btn('다시 점검하기','render','tiny')}</div>${list.length?issueCards(list):'<div class="success-note">필수 입력·연결·참조·명시적 값 검사에서 남은 항목이 없습니다. 의미와 적합성은 아래에서 직접 확인하세요.</div>'}<div class="section-title"><h2>내 의도와 서비스 적합성 확인</h2><small>사용자 직접 판단</small></div><div class="intent-box"><h3>이 설계는 만들고 싶었던 것과 맞나요?</h3><p>고객과 제공 결과, 의문과 근거, 전체 흐름, 분위기의 적합성, 적용 범위, 미정 자료를 확인하세요. 일부를 바꾸면 기존 입력을 유지한 채 보완할 수 있습니다.</p><label class="small-label" for="intent-reason">확인한 이유 또는 바꿀 내용</label><textarea class="input" id="intent-reason" placeholder="이 방향이 사용자와 목표에 맞는 이유를 적어 주세요.">${esc(p.intent?.reason||'')}</textarea><div class="row wrap" style="margin-top:15px">${btn('의도와 맞음 · 이 기준 확인','confirm-intent','primary tiny')}${btn('일부 수정 · 설계 보완','intent-edit','tiny')}${btn('방향 다시 검토','intent-rethink','tiny')}</div>${p.intent?`<small>r${p.intent.revision} 기준 · 사용자 확인: ${esc(p.intent.reason)}</small>`:''}</div><details style="margin-top:20px"><summary>사용자가 확인할 의미 충돌 질문</summary><div class="learning-note">작은 픽셀 글자가 긴 한글 설명을 방해하지 않나요?<br>장식이 실제 사진·제품·작업 대상을 가리지 않나요?<br>여러 컨셉의 요소를 섞었을 때 주인공과 읽는 순서가 유지되나요?<br>자료가 없는 기능·정책·성과를 있는 것처럼 쓰지 않았나요?</div></details>${footer('prompt','완성된 디자인 프롬프트 만들기','확정한 결정과 첨부 자료를 버전 있는 템플릿으로 조립합니다.')}`;}
function basePromptView(){const snap=p.snapshots.find(s=>s.id===activeSnapshot)||p.snapshots.at(-1);if(snap)activeSnapshot=snap.id;const list=issues(p);return `<div class="detail-grid"><div>${simple('출력 목적','output.purpose',{options:['서비스 전체 UI UX 설계','특정 흐름 또는 화면 설계','기존 디자인 조정','리소스 제작 요청']})}${simple('산출 형식','output.format',{options:['UI UX 설계 문서','편집 가능한 화면 시안','코드로 구현한 UI','시각 방향 확인용 이미지','리소스 제작 지시']})}</div><div>${simple('이번에 전달할 범위','output.scope')}${simple('알려진 기술 환경 (미정 허용)','output.tech')}</div></div>${p.output.format==='시각 방향 확인용 이미지'?'<div class="learning-note" style="margin-top:15px">이미지는 시각적 장면을 표현합니다. 동작과 복구는 구현 후 별도로 실행해 확인해야 합니다.</div>':''}<details style="margin:19px 0"><summary>공통 기준과 작업 절차 · v${p.output.commonVersion}</summary>${simple('재사용할 공통 기준','output.common',{area:true})}${simple('작업 절차 · 실행되지 않는 문서 참조','output.procedure',{area:true})}${simple('절차 출처 또는 스킬 문서 경로','output.procedureSource')}</details>${simple('사용자 추가 지시 · 재조립해도 유지됩니다','output.extra',{area:true,placeholder:'구조화된 결정 외에 전달할 내용을 적으세요.'})}${p.output.extra?'<div class="learning-note" style="margin-top:10px">추가 지시는 원문으로 보존됩니다. 구조화된 결정과 의미가 충돌하지 않는지 직접 확인해 주세요.</div>':''}<div class="row wrap" style="margin:23px 0">${btn(icon('prompt')+'완성된 디자인 프롬프트 만들기','assemble','primary')}${btn('미정 내용을 남긴 초안 만들기','assemble-draft','tiny')}</div>${!ready(p)?`<div class="learning-note">${list.length?`확정하거나 보완할 항목 ${list.length}개가 있습니다.`:'생성 전 사용자 의도 확인이 필요합니다.'} ${btn('필요한 결정부터 보완하기','remedy','tiny','data-tab="brief"')}</div>`:''}${snap?`<div class="section-title"><h2>통합 프롬프트</h2><select class="input small-input" id="snapshot-select" aria-label="프롬프트 버전" style="width:auto;max-width:230px">${p.snapshots.map(s=>`<option value="${s.id}" ${s.id===snap.id?'selected':''}>v${s.number} · ${s.planId?'수정 통합본':s.draft?'초안':'확정 통합본'} · r${s.revision}</option>`).join('')}</select></div>${snap.revision!==p.revision?'<div class="issue">현재 결정이 이 스냅샷 이후 변경되었습니다. 기존 문서는 유지됩니다. 필요한 결정을 확인하고 새 버전으로 조립하세요.</div>':''}<div class="row wrap" style="margin-bottom:14px">${btn('전체 문서 복사','copy','tiny',`data-id="${snap.id}"`)}${btn('Markdown 내려받기','markdown','tiny',`data-id="${snap.id}"`)}${btn(icon('download')+'참고 자료 ZIP','bundle','tiny',`data-id="${snap.id}"`)}${btn('결정 추적 보기','trace','tiny',`data-id="${snap.id}"`)}</div><pre class="prompt-preview">${esc(snap.text)}</pre><small>${snap.templateVersion} · 결정 ${snap.decisions.length}개 · 원본·크롭·첨부 ${snap.referenceFileIds.length}개 · ${fmtDate(snap.createdAt)}</small><details style="margin-top:18px"><summary>전달할 자료와 미확보 리소스 구분</summary><div class="learning-note"><strong>텍스트에 포함</strong> 고객·전체 흐름·확정 스타일·검토·수정 기준<br><strong>실제 파일로 포함</strong> ${snap.referenceFileIds.map(id=>esc(files.find(f=>f.id===id)?.name||id)).join(', ')||'없음'}<br><strong>외부에서 별도 제공 / 아직 미확보</strong> ${p.assets.filter(a=>!a.fileId).map(a=>esc(a.value)+' ('+esc(a.availability)+')').join(', ')||'별도 등록 없음'}</div></details><section class="handoff"><h3>이제 외부 도구에 전달해 주세요.</h3><ol><li>전체 프롬프트를 복사하거나 Markdown을 엽니다.</li><li>ZIP을 풀어 원본·크롭과 실제 자료를 해당 도구에 직접 첨부합니다.</li><li>결과가 나오면 이 프로젝트의 <strong>자가 진단과 수정</strong>에 등록합니다.</li></ol><p style="font-size:10px;color:var(--muted);margin-bottom:13px">이 작업실은 외부 제작을 실행하거나 진행률을 조회하지 않습니다.</p><div class="row wrap">${btn('이 버전을 전달했어요 · 결과 대기','mark-handoff','tiny',`data-id="${snap.id}"`)}${btn('결과가 나왔어요 · 직접 등록','result-from-snapshot','primary tiny',`data-id="${snap.id}"`)}</div></section>`:empty('Your decisions, in one place.','직접 확정한 입력과 템플릿으로 재현 가능한 하나의 프롬프트를 만듭니다. 먼저 초안으로 구조를 살펴볼 수도 있어요.','현재 내용으로 초안 만들기','assemble-draft')}`;}
function promptView(){if(p.settings.density==='quick')return outputScopeEditor(p)+basePromptView();const html=basePromptView(),split=html.indexOf('<div class="row wrap" style="margin:23px 0">');return '<div class="easy-guide"><h2>디자인을 요청할 문서가 준비됐어요.</h2><p class="easy-intro">확인한 내용을 하나의 프롬프트로 만드세요. 복사한 문서와 참고 파일을 사용할 외부 제작 도구에 직접 전달하면 됩니다.</p><div class="easy-note"><strong>기본 출력: 프로젝트 전체 UI·UX 설계 문서</strong><p>지금까지 확인한 기능·사용 순서·스타일·검토 기준을 포함합니다. 파일 내보내기는 제작을 자동 실행하지 않습니다.</p></div><details class="easy-extra"><summary>출력 형식·특정 화면·추가 요청 바꾸기 (선택)</summary>'+outputScopeEditor(p)+html.slice(0,split)+'</details>'+html.slice(split)+'</div>';}
function reviewView(){const r=p.reviews.find(r=>r.id===activeReview)||p.reviews.at(-1);if(r)activeReview=r.id;const result=r?p.results.find(x=>x.id===r.resultId):null;const snap=r?p.snapshots.find(s=>s.id===r.snapshotId):null;return `<div class="row wrap" style="margin-bottom:20px">${p.progress.planDraft?btn('저장한 수정 계획 이어쓰기','resume-plan','tiny'):''}${btn(icon('image')+'실제 결과 등록하기','register-result','primary tiny')}${btn(p.snapshots.length?'의도 변경 · 새 기준 버전':'원래 의도로 진단 기준 먼저 고정','baseline','tiny')}${p.reviews.length?`<select class="input small-input" id="review-select" aria-label="검토 회차" style="width:auto;max-width:290px">${p.reviews.map((x,i)=>`<option value="${x.id}" ${x.id===r.id?'selected':''}>${i+1}회차 · ${x.parentReviewId?'재검토':'첫 비교'} · ${esc(p.results.find(a=>a.id===x.resultId)?.screen||'결과')}</option>`).join('')}</select>`:''}</div>${!r?empty('A result is a new beginning.','원래 의도와 실제 결과를 연결하세요. 기존 결과에서 시작했다면 아는 기준을 먼저 고정할 수 있습니다. 없는 결과를 검토한 것처럼 표시하지 않습니다.','원래 의도로 진단 기준 고정하기','baseline'):`<div class="row between wrap"><span class="tag ${r.state==='completed'?'confirmed':'proposed'}">${({reviewing:'결과 진단 중','needs-revision':'수정 필요',completed:r.scope==='visual'?'해당 화면 시각 확인 완료':'해당 범위 동작 포함 확인 완료',held:'보류 · 완료와 구분'})[r.state]}</span><small>기준 v${snap.number} / 결과 v${result.number} / ${esc(result.source)}</small></div><div class="comparison"><figure><figcaption>당시 확정 기준 · ${esc(snap.input?.name||p.name)} · v${snap.number}</figcaption>${snap.input?.references?.find(a=>a.fileId&&fileExists(a.fileId))?`<img src="${fileURL(snap.input.references.find(a=>a.fileId&&fileExists(a.fileId)).fileId)}" alt="당시 레퍼런스 원본">`:`<p>${esc(snap.criteria.find(c=>c.id==='style')?.expected||'직접 작성한 기준')}${snap.baselineReason?'\n기준 고정 이유: '+esc(snap.baselineReason):''}</p>`}</figure><figure><figcaption>실제 결과 · ${esc(result.screen)} · ${esc(result.environment)}</figcaption>${result.fileId&&fileExists(result.fileId)?`<img src="${fileURL(result.fileId)}" alt="사용자가 등록한 실제 결과">`:'<p>결과 이미지 없음 · 직접 실행 기록으로 확인</p>'}</figure></div><div class="learning-note"><strong>등록한 원문</strong><p>${esc(result.note||'별도 메모 없음')}</p><p>사용한 지시: ${esc(result.instruction||'연결된 프롬프트 버전')}<br>유지할 요소: ${esc(result.keep||'아직 작성하지 않음')}<br>실행 기록: ${esc(result.execution||'없음 · 스크린샷으로 동작을 검증할 수 없습니다.')}</p></div>${r.parentReviewId?`<div class="issue">이전 회차 ${p.reviews.findIndex(x=>x.id===r.parentReviewId)+1}에서 이어진 재검토입니다. 판정은 복사하지 않았습니다. 같은 기준과 영향받는 기존 일치 항목을 새 근거로 다시 확인하세요.</div>`:''}<div class="review-bar"><label class="small-label" style="margin:0">이번 검토 범위</label><select class="input small-input" data-path="reviews.${p.reviews.indexOf(r)}.scope" aria-label="이번 검토 범위"><option value="visual" ${r.scope==='visual'?'selected':''}>등록한 화면의 시각 표현</option><option value="behavior" ${r.scope==='behavior'?'selected':''}>동작 포함 · 실행 기록 필요</option></select><small>시각 확인만으로 서비스 전체를 검증하지 않습니다.</small></div>${reviewItems(r)}<div class="intent-box"><h3>실제 결과가 원래 의도와 맞나요?</h3><div class="verdict">${[['match','의도와 맞음'],['partial','일부 다름'],['different','방향이 다름'],['unknown','아직 판단 어려움']].map(([v,l])=>`<button class="${r.intent===v?'active':''}" data-action="review-intent" data-id="${r.id}" data-value="${v}">${l}</button>`).join('')}</div>${simple('판단한 이유와 유지·변경할 점',`reviews.${p.reviews.indexOf(r)}.intentReason`,{area:true})}</div><details style="margin:20px 0"><summary>직접 가져온 외부 피드백과 학습 기록</summary>${simple('외부 피드백 원문 (선택, 자동 응답 아님)',`reviews.${p.reviews.indexOf(r)}.externalFeedback`,{area:true})}${simple('외부 피드백의 실제 출처',`reviews.${p.reviews.indexOf(r)}.feedbackSource`)}${simple('이번 비교에서 배운 점',`reviews.${p.reviews.indexOf(r)}.learning`,{area:true})}${btn('학습 기록 Markdown','learning-export','tiny',`data-id="${r.id}"`)}${btn('선택한 원칙을 공통 기준 후보로','reuse-learning','tiny',`data-id="${r.id}"`)}</details><div class="row wrap" style="margin-top:22px">${btn('선택한 차이로 수정 계획 만들기','plan','primary',`data-id="${r.id}"`)}${btn('해당 검토 범위 확인 완료','complete-review','tiny',`data-id="${r.id}"`)}${btn('이유를 남기고 보류','hold-review','ghost tiny',`data-id="${r.id}"`)}</div>${r.state==='held'?`<div class="issue">보류 이유: ${esc(r.holdReason)}</div>`:''}${p.plans.filter(a=>a.reviewId===r.id).map(plan=>planView(plan)).join('')}<details style="margin-top:25px"><summary>완료까지 남은 항목</summary>${reviewProblems(p,r).map(x=>`<p style="font-size:10px;color:var(--muted);margin:7px 0">— ${esc(x)}</p>`).join('')||'<small>이 범위의 필수 근거와 사용자 확인이 준비되었습니다.</small>'}</details>`}`;}
function reviewItem(r,item,i){const base=`reviews.${p.reviews.indexOf(r)}.items.${i}`,excluded=r.scope==='visual'&&item.scope==='behavior';return `<article class="review-item"><div class="row between"><span class="eyebrow">${item.scope==='behavior'?'SERVICE & INTERACTION':'VISUAL & INTENTION'} / ${String(i+1).padStart(2,'0')}</span>${item.regression?'<span class="tag review">기존 일치 · 회귀 확인</span>':''}</div><h3>${esc(item.label)}</h3><div class="expected"><strong>당시 기대와 기준</strong><br>${esc(item.expected)}</div>${excluded?'<div class="learning-note">동작 확인은 이번 시각 검토의 완료 범위에서 제외됩니다. 실행 근거가 없으면 확인 불가로 유지하세요.</div>':''}<div class="detail-grid"><div>${simple('실제 결과에서 무엇을 관찰했나요?',base+'.observation',{area:true})}</div><div>${simple('관찰 근거 · 화면/영역 또는 실행 기록',base+'.evidence',{area:true,placeholder:'예: 상태 패널의 숫자 영역 / 입력값 변경 후 표시 결과'})}</div></div><div class="verdict" role="group" aria-label="${esc(item.label)} 판정">${[['match','일치'],['partial','부분 일치'],['mismatch','불일치'],['unverifiable','확인 불가'],['na','해당 없음']].map(([v,l])=>`<button class="${item.verdict===v?'active':''}" data-action="verdict" data-review="${r.id}" data-index="${i}" data-value="${v}">${l}</button>`).join('')}</div><details ${['partial','mismatch'].includes(item.verdict)?'open':''}><summary>수정할 곳과 유지할 부분 기록</summary><div class="detail-grid"><div>${simple('수정 대상 · 브리프/흐름/스타일/리소스/구현',base+'.target')}${simple('원인 가설 (판정한 사실과 구별)',base+'.cause')}</div><div>${simple('유지할 조건',base+'.keep')}${r.parentReviewId?simple('새 결과의 재검토 판정',base+'.resolution',{options:['unverifiable','resolved','remaining','new-problem']}):''}</div></div></details><label class="small-label" style="margin-top:12px"><input type="checkbox" data-path="${base}.selected" ${item.selected?'checked':''}> 이 항목을 수정 계획에 포함</label></article>`;}
function planView(plan){return `<section class="item" style="margin-top:25px"><div class="row between"><h3 style="font-size:14px">수정 계획</h3><span class="tag ${plan.confirmed?'confirmed':'proposed'}">${plan.confirmed?'사용자 확정':'검토 필요'}</span></div><div class="brief-line"><dt>문제와 근거</dt><dd>${esc(plan.problem)}</dd></div><div class="brief-line"><dt>원인 / 대상</dt><dd>${esc(plan.cause)} / ${esc(plan.target)}</dd></div><div class="brief-line"><dt>변경 / 유지</dt><dd>${esc(plan.change)}<br>유지: ${esc(plan.keep)}</dd></div><div class="brief-line"><dt>범위 / 재검토</dt><dd>${esc(plan.scope)}<br>${esc(plan.check)}</dd></div><div class="row wrap">${btn('이 계획 편집하기','edit-plan','tiny',`data-id="${plan.id}"`)}${btn(plan.confirmed?'확정 계획으로 수정 통합본 만들기':'이 계획 확정 후 수정 통합본 만들기','revision-prompt','primary tiny',`data-id="${plan.id}"`)}</div><small>수정 프롬프트를 만든 것만으로 문제를 해결됨으로 표시하지 않습니다.</small></section>`;}

function showModal(title,html,{wide=false}={}){modalReturn=document.activeElement;$('#modal-root').innerHTML=`<div class="modal-overlay"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modal-head"><h2>${title}<span class="accent">.</span></h2><button class="btn ghost tiny" data-action="close-modal" aria-label="닫기">✕</button></div>${html}</section></div>`;setTimeout(()=>$('.modal input:not([type=file]),.modal textarea,.modal button')?.focus(),30);}
function closeModal(){ if(pendingFiles){toast('현재 프로젝트에 파일을 저장하는 중입니다. 완료 후 닫을 수 있습니다.');return;} $('#modal-root').innerHTML='';modalReturn?.focus?.();}
function createModal(entry='idea'){creationEntry=entry;showModal('A new beginning',`<p>이름, 자유로운 설명, 지금의 시작점. 세 가지만 있으면 됩니다.</p><label class="small-label" for="new-name">프로젝트 이름</label><input class="input" id="new-name" maxlength="120" placeholder="예: 나의 첫 번째 디자인 프로젝트"><label class="small-label" for="new-idea">만들고 싶은 것 · 자유로운 원문</label><textarea class="input" id="new-idea" placeholder="무엇을 만들고 싶나요? 이미 정한 컨셉이 있다면 함께 적어 주세요."></textarea><label class="small-label">지금 어디에 있나요?</label><div class="entry-grid">${ENTRIES.map(e=>`<button class="entry-card ${entry===e[0]?'selected':''}" data-action="entry-select" data-entry="${e[0]}"><h3>${e[1]}</h3><p>${e[2]}</p></button>`).join('')}</div><div class="modal-actions">${btn('내 작업실로 돌아가기','close-modal','ghost')}${btn(ENTRIES.find(e=>e[0]===entry)[4]+' →','create-submit','primary','id="create-submit"')}</div>`);}
function singleTextModal(title,label,value,action,{area=true,help=''}={}){showModal(title,`${help?`<p>${help}</p>`:''}<label class="small-label" for="modal-text">${label}</label>${area?`<textarea class="input" id="modal-text">${esc(value)}</textarea>`:`<input class="input" id="modal-text" value="${esc(value)}">`}<div class="modal-actions">${btn('취소','close-modal','ghost')}${btn('이 내용으로 저장',''+action,'primary')}</div>`);}
function settingsModal(){showModal('Your workspace',`<p>외부 연결 없이 모든 핵심 작업을 사용할 수 있습니다. 원본 이미지는 브라우저 임시 주소가 아니라 서버의 프로젝트 폴더에 보관됩니다.</p>${p?`<div class="detail-grid"><div>${simple('프로젝트 이름','name')}${simple('시작 경로','entry',{options:ENTRIES.map(x=>x[0])})}</div><div>${simple('기본 출력 언어','output.language')}${simple('편집 밀도','settings.density',{options:['guide','quick']})}</div></div><div class="rule"></div><h3>프로젝트 데이터</h3><p>JSON 백업에는 데이터와 원본·크롭·결과 이미지 및 참조가 함께 들어갑니다. 복원은 새 프로젝트를 만들고 기존 작업은 보존합니다.</p><div class="row wrap">${btn('데이터와 원본 백업','backup','tiny')}${btn('JSON 백업 복원','restore','tiny')}${btn('저장되지 않은 입력 내려받기','draft-download','tiny')}</div><div class="rule"></div><h3>공통 작업 기준 · v${p.output.commonVersion}</h3>${simple('이 프로젝트에서 사용하는 공통 기준','output.common',{area:true})}${simple('작업 절차 또는 스킬 참조 (자동 실행하지 않음)','output.procedureSource')}${btn('이 기준을 새 프로젝트 기본값으로 사용','save-common','tiny')}`:`<h3>새 프로젝트의 기본 작업 기준</h3><textarea class="input" id="global-common">${esc(settings.common||COMMON_DEFAULT)}</textarea>${btn('이 기본 기준 저장','save-global-common','tiny')}${btn('프로젝트 백업 복원','restore','tiny')}`}<div class="rule"></div><h3>자료와 서체</h3><p>영문: Instrument Serif · Instrument Sans (SIL OFL). 한글: 시스템의 맑은 고딕 등.<br><a href="https://streamlinehq.com" target="_blank" rel="noopener">Free icons from Streamline ↗</a> · Pixel 공식 공개 SVG 13개, 메뉴와 버튼에 사용.</p><h3>연결 기능의 경계</h3><p>현재는 프롬프트 조립·파일 내보내기·수동 결과 등록만 제공합니다. 후속 외부 서비스의 인증·API는 구현하거나 가정하지 않았습니다.</p>${p?`<div class="rule"></div>${btn('이 프로젝트와 연결 파일 삭제','delete-project','danger tiny')}`:''}<div class="modal-actions">${btn('작업으로 돌아가기','settings-close','primary')}</div>`,{wide:true});}
function locate(id){if(!id)return;const el=document.getElementById('field-'+id)||$$('[data-locate]').find(e=>e.dataset.locate===id);if(el){if(el.tagName==='DETAILS')el.open=true;el.closest('details')&&(el.closest('details').open=true);el.scrollIntoView({block:'center',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});el.classList.remove('flash');void el.offsetWidth;el.classList.add('flash');el.querySelector('textarea,input,select')?.focus({preventScroll:true});}}
async function navigate(tab,id,{remedy=false}={}){if(remedy&&tab!==currentTab())p.progress.returnTo={tab:currentTab(),guideStage:p.progress.guideStage};p.progress.tab=tab;if(tab==='design'&&id){const q=QUESTIONS.find(q=>q.key===id||p.fields[q.key].id===id);if(q)p.progress.guideStage=q.group;}changed();await flush();renderTop();if(id)setTimeout(()=>locate(id),70);}
function download(name,text,type='text/plain'){const blob=text instanceof Blob?text:new Blob([text],{type});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),3000);}
async function downloadAPI(route,name){await flush();const response=await fetch('/api'+route);if(!response.ok){const e=await response.json();throw new Error(e.error);}download(name,await response.blob());}
async function toData(file,role='image'){if(file.size>15*1024*1024)throw new Error('파일당 최대 15MB입니다. 원본 입력은 유지됩니다.');if(role==='image'&&!['image/png','image/jpeg','image/webp'].includes(file.type))throw new Error('PNG·JPEG·WebP만 등록할 수 있습니다.');if(role==='image')try{const bitmap=await createImageBitmap(file);if(bitmap.width*bitmap.height>40e6){bitmap.close();throw new Error('이미지 해상도는 4천만 픽셀 이하여야 합니다.');}bitmap.close();}catch(e){throw new Error('이미지를 열 수 없습니다. PNG·JPEG·WebP 파일을 다시 확인해 주세요.');}return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(String(r.result).split(',')[1]);r.onerror=()=>reject(new Error('파일을 읽지 못했습니다. 다시 등록해 주세요.'));r.readAsDataURL(file);});}
async function upload(file,role='image'){
 if(!p)throw new Error('프로젝트를 먼저 만드세요.');
 if(pendingFiles)throw new Error('현재 파일의 등록이 끝난 뒤 다음 파일을 선택해 주세요.');
 const owner=p,projectId=p.id;pendingFiles=projectId;
 $('.content-shell')?.insertAdjacentHTML('afterbegin',`<div class="learning-note" id="upload-state" role="status">${esc(p.name)} 프로젝트에 ${esc(file.name)} 파일을 저장하고 있습니다. 원본과 연결을 보존하기 위해 등록이 끝난 뒤 다른 작업으로 이동할 수 있습니다.</div>`);
 try{const data=await toData(file,role);const f=await api('/projects/'+projectId+'/files','POST',{data,name:file.name,mime:file.type,role},{signal:AbortSignal.timeout(30000)});if(p!==owner)throw new Error('프로젝트가 바뀌어 파일의 자동 연결을 중단했습니다. 원본 프로젝트에서 다시 등록해 주세요.');files.push({...f,exists:true});return f;}
 catch(error){if(error.name==='TimeoutError')throw new Error('파일 저장이 지연되었습니다. 입력은 유지했습니다. 같은 파일을 다시 선택해 주세요.');throw error;}
 finally{pendingFiles=null;$('#upload-state')?.remove();}
}
function chooseFile(handler){const el=document.createElement('input');el.type='file';el.accept='image/png,image/jpeg,image/webp';el.onchange=()=>handler(el.files[0]).catch(e=>toast(e.message,true));el.click();}
async function addReference(file,replaceId){const f=await upload(file);if(replaceId){const r=p.references.find(x=>x.id===replaceId);r.fileId=f.id;r.regions.forEach(a=>a.reviewNeeded=true);touch(p,'레퍼런스 원본 교체 — 기존 영역 재검토',[r.id]);}else{const r={id:uid('ref'),name:file.name,url:'',note:'',role:'좋아하는 전체 느낌',fileId:f.id,regions:[]};p.references.push(r);activeRef=r.id;touch(p,'레퍼런스 원본 등록');}changed();await flush();render();toast('원본 저장 완료. 관찰할 영역을 선택해 주세요.');}
async function createRegion(r,rect,existingId){const img=$('#reference-original');if(!img?.naturalWidth)throw new Error('원본 이미지를 읽은 뒤 영역을 다시 선택해 주세요.');const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(img.naturalWidth*rect.w));canvas.height=Math.max(1,Math.round(img.naturalHeight*rect.h));if(canvas.width*canvas.height>16e6){const scale=Math.sqrt(16e6/(canvas.width*canvas.height));canvas.width=Math.round(canvas.width*scale);canvas.height=Math.round(canvas.height*scale);}canvas.getContext('2d').drawImage(img,img.naturalWidth*rect.x,img.naturalHeight*rect.y,img.naturalWidth*rect.w,img.naturalHeight*rect.h,0,0,canvas.width,canvas.height);const b=await new Promise(resolve=>canvas.toBlob(resolve,'image/png'));const f=await upload(new File([b],`${r.name}-A${r.regions.length+1}.png`,{type:'image/png'}));if(existingId){const existing=r.regions.find(a=>a.id===existingId);updateDecision(p,existing,{fileId:r.fileId,cropId:f.id,rect,reviewNeeded:true},'reference');changed();await flush();render();toast('새 원본으로 크롭을 갱신했습니다. 관찰과 적용을 다시 확인하세요.');return;}const a=decision('','observation','unknown',{fileId:r.fileId,cropId:f.id,rect,dimension:'색 관계',observation:'',interpretation:'',target:'',purpose:'',keep:'',change:'',avoid:'',useMode:'시각 원리 참고'});r.regions.push(a);touch(p,'원본에 연결한 선택 영역 등록',[a.id]);changed();await flush();render();setTimeout(()=>locate(a.id),60);}
function bindReference(){const el=$('#reference-stage');if(!el)return;let start,box;const point=e=>{const b=el.getBoundingClientRect();return {x:Math.max(0,Math.min(1,(e.clientX-b.left)/b.width)),y:Math.max(0,Math.min(1,(e.clientY-b.top)/b.height))};};el.onpointerdown=e=>{if(e.button!==0)return;start=point(e);box=document.createElement('div');box.className='region-box';el.append(box);el.setPointerCapture(e.pointerId);e.preventDefault();};el.onpointermove=e=>{if(!start)return;const end=point(e);Object.assign(box.style,{left:Math.min(start.x,end.x)*100+'%',top:Math.min(start.y,end.y)*100+'%',width:Math.abs(end.x-start.x)*100+'%',height:Math.abs(end.y-start.y)*100+'%'});};el.onpointerup=e=>{if(!start)return;const end=point(e),rect={x:Math.min(start.x,end.x),y:Math.min(start.y,end.y),w:Math.abs(end.x-start.x),h:Math.abs(end.y-start.y)};start=null;box.remove();if(rect.w<.015||rect.h<.015){toast('조금 더 넓게 드래그하거나 전체 이미지 영역을 선택하세요.');return;}createRegion(p.references.find(x=>x.id===el.dataset.id),rect).catch(e=>toast(e.message,true));};el.onpointercancel=()=>{start=null;box?.remove();};}
function bindHero(){const art=$('#hero-art');if(!art||matchMedia('(prefers-reduced-motion: reduce)').matches||!matchMedia('(pointer:fine)').matches)return;art.addEventListener('pointermove',e=>{const b=art.getBoundingClientRect();const x=(e.clientX-b.left)/b.width,y=(e.clientY-b.top)/b.height;const note=art.querySelector('.cursor-note');note.style.left=45+x*25+'%';note.style.top=45+y*24+'%';art.querySelector('.front').style.transform=`rotate(${6+x*6}deg) translate(${65+x*6}px,${-7+y*7}px)`;});}
function resultModal(snapshotId){if(!p.snapshots.length){toast('먼저 당시 의도를 고정하세요. 완성 프롬프트가 없어도 진단용 기준을 만들 수 있습니다.');return baselineModal();}showModal('Bring the result back',`<p>외부에서 만든 실제 결과를 등록합니다. 연결할 버전을 직접 확인하세요. 이전 버전에 연결해도 최신 편집은 덮어쓰지 않습니다.</p><label class="small-label">연결할 기준·프롬프트 버전</label><select class="input" id="result-snapshot">${p.snapshots.map(s=>`<option value="${s.id}" ${s.id===(snapshotId||p.handoff?.snapshotId||p.snapshots.at(-1).id)?'selected':''}>v${s.number} · ${s.planId?'수정 통합본':s.draft?'진단 기준 또는 초안':'통합본'} · r${s.revision}</option>`).join('')}</select><div class="detail-grid"><div><label class="small-label">화면이나 상태 이름</label><input class="input" id="result-screen" placeholder="예: 현재 상태 화면 / 게임 진행 화면 / 응답 결과 화면"><label class="small-label">사용 환경</label><input class="input" id="result-environment" value="${esc(p.fields.environment.value||'미정')}"></div><div><label class="small-label">실제 출처 (도구 또는 작성자, 버전 메모)</label><input class="input" id="result-source" placeholder="직접 사용한 외부 도구 또는 제작자"><label class="small-label">사용한 지시</label><input class="input" id="result-instruction" placeholder="연결한 버전과 달랐다면 기록"></div></div><label class="small-label">실제 결과 이미지</label><input class="input" type="file" accept="image/png,image/jpeg,image/webp" id="result-file"><label class="small-label">직접 확인한 실행 기록 (이미지 대신 또는 보완)</label><textarea class="input" id="result-execution" placeholder="실행한 조작·환경·관찰 결과. 스크린샷만 있으면 비워 두세요."></textarea><label class="small-label">원하는 변화와 느낀 문제</label><textarea class="input" id="result-note"></textarea><label class="small-label">유지할 요소</label><input class="input" id="result-keep"><div class="modal-actions">${btn('취소','close-modal','ghost')}${btn('이 버전에 연결하고 기준별 비교하기','result-submit','primary')}</div>`,{wide:true});}
function baselineModal(){singleTextModal('Fix a starting point','기존 결과의 원래 의도와 기준 고정 이유','','baseline-submit',{help:'현재 작성한 제품·스타일 기준을 진단용 스냅샷으로 보관합니다. 미정 항목은 확인 필요로 남습니다. 기준을 바꿀 때는 새 이유와 버전을 기록합니다.'});}
function planModal(r,existing){if(p.settings.density==='quick')return basePlanModal(r,existing);const items=r.items.filter(i=>i.selected);if(!existing&&!items.length)throw new Error('바꾸고 싶은 비교 항목에서 “이 항목을 수정 계획에 포함”을 선택해 주세요.');const data=existing||{problem:items.map(i=>i.label+': '+i.observation+' / 근거: '+i.evidence).join('\n'),cause:'원인은 아직 확인하지 않음',target:items.map(i=>i.target).filter(Boolean).join('; ')||'등록한 결과 화면',change:'',scope:r.screen||'등록한 결과 화면',keep:items.map(i=>i.keep).filter(Boolean).join('; '),materials:'연결된 기준 문서와 등록한 결과',check:items.map(i=>i.label+': '+i.expected).join('\n')};showModal('무엇을 어떻게 바꿀까요?',`<div class="easy-guide"><p class="easy-intro">선택한 차이와 관찰 근거는 가져왔어요. 바꿀 모습과 유지할 것만 정하면 됩니다. 원인은 아직 몰라도 괜찮아요.</p><div class="easy-note"><strong>선택한 문제</strong><p>${esc(data.problem)}</p></div>${[['change','어떻게 바뀌면 좋을까요?','예: 제출 완료 안내 아래에 응답 수정 버튼을 보여 주기'],['scope','어느 화면이나 부분을 바꿀까요?','예: 제출 완료 화면의 안내와 버튼'],['keep','지금 그대로 유지할 것은 무엇인가요?','예: 질문과 선택지, 기존 색과 글자 크기']].map(([key,label,placeholder])=>`<label class="easy-label" for="plan-${key}">${label}</label><textarea class="input" id="plan-${key}" placeholder="${placeholder}">${esc(data[key])}</textarea>`).join('')}<label class="easy-label" for="plan-check">바꾼 결과에서 다시 확인할 것</label><textarea class="input" id="plan-check">${esc(data.check)}</textarea><details class="easy-extra"><summary>문제 원문·원인·대상·자료 보완 (선택)</summary>${[['problem','선택한 문제와 관찰 근거'],['cause','문제가 생긴 이유 · 모르면 아직 확인하지 않음'],['target','바꿀 대상'],['materials','함께 전달할 자료']].map(([key,label])=>`<label class="easy-label" for="plan-${key}">${label}</label><textarea class="input" id="plan-${key}">${esc(data[key])}</textarea>`).join('')}</details><div class="modal-actions">${btn('취소','close-modal','ghost')}${btn('수정 계획 저장하기','plan-submit','primary',`data-review="${r.id}" ${existing?.id?`data-id="${existing.id}"`:''}`)}</div></div>`,{wide:true});}
function basePlanModal(r,existing){const items=r.items.filter(i=>i.selected);if(!existing&&!items.length)throw new Error('먼저 수정할 진단 항목의 “수정 계획에 포함”을 선택하세요.');const fields=existing||{problem:items.map(i=>`${i.label}: ${i.observation} / 근거: ${i.evidence}`).join('\n'),cause:items.map(i=>i.cause).filter(Boolean).join('; '),target:items.map(i=>i.target).filter(Boolean).join('; '),change:'',scope:r.screen||'등록한 화면',keep:items.map(i=>i.keep).filter(Boolean).join('; '),materials:'현재 기준과 등록한 실제 결과',check:items.map(i=>i.label+': '+i.expected).join('\n')};showModal('A plan with a purpose',`<p>문제·변경 범위·유지할 조건을 정합니다. 원인 가설을 직접 고르고, 부족하면 관련 결정부터 보완할 수 있습니다.</p>${[['problem','문제와 실제 관찰 근거'],['cause','원인 가설 · 의도 부족/스타일 해석/레퍼런스/리소스/구현/요구 변경'],['target','수정 대상 · 브리프/흐름/스타일/리소스/구현'],['change','변경 목표 · 무엇이 어떻게 달라져야 하나요?'],['scope','변경 범위와 해당 화면'],['keep','유지할 조건 · 이미 맞는 부분'],['materials','필요한 자료'],['check','같은 기준으로 다시 확인할 방법']].map(([k,l])=>`<label class="small-label">${l}</label><textarea class="input" id="plan-${k}">${esc(fields[k]||'')}</textarea>`).join('')}<div class="row wrap" style="margin-top:15px">${btn('브리프 보완 후 돌아오기','plan-remedy','tiny','data-tab="design"')}${btn('스타일 보완 후 돌아오기','plan-remedy','tiny','data-tab="style"')}${btn('레퍼런스 보완 후 돌아오기','plan-remedy','tiny','data-tab="reference"')}</div><div class="modal-actions">${btn('취소','close-modal','ghost')}${btn('수정 계획 저장 · 아직 해결 아님','plan-submit','primary',`data-review="${r.id}" ${existing?.id?`data-id="${existing.id}"`:''}`)}</div>`,{wide:true});}

const actions={
 'graph-add':el=>{const f=p.flows.find(f=>f.id===el.dataset.flow);editGraph(p,f,g=>g.transitions.push({id:uid('edge'),from:f.steps[0]||'',to:'',kind:'branch',condition:'',preserve:''}));changed();render();const rows=$(`[data-locate="${f.id}"] .graph-rows`);if(rows)rows.open=true;},
 'graph-remove':el=>{const f=p.flows.find(f=>f.id===el.dataset.flow);editGraph(p,f,g=>g.transitions=g.transitions.filter(e=>e.id!==el.dataset.id));changed();render();},
 'graph-terminal':el=>{const f=p.flows.find(f=>f.id===el.dataset.flow);editGraph(p,f,g=>g.terminalIds=el.checked?[...new Set([...g.terminalIds,el.value])]:g.terminalIds.filter(id=>id!==el.value));changed();render();},
 'graph-sequence':el=>{const f=p.flows.find(f=>f.id===el.dataset.flow);editGraph(p,f,g=>{const base=createGraph(f);g.transitions=[...base.transitions,...g.transitions.filter(e=>['branch','recovery'].includes(e.kind))];if(!f.steps.includes(g.entryId))g.entryId=f.steps[0]||'';g.terminalIds=g.terminalIds.filter(id=>f.steps.includes(id));if(!g.terminalIds.length&&f.steps.length)g.terminalIds=[f.steps.at(-1)];});changed();render();},
 'graph-ack':el=>{const f=p.flows.find(f=>f.id===el.dataset.flow);acknowledgeGraph(p,f);changed();render();toast('실제 연결·분기·복구 기준을 확인했습니다. 화면별 변경 영향은 별도로 확인해 주세요.');},
 'move-step':el=>{const f=p.flows.find(f=>f.id===el.dataset.flow),steps=[...f.steps],i=steps.indexOf(el.dataset.id),j=i+Number(el.dataset.direction);if(i<0||j<0||j>=steps.length)return;[steps[i],steps[j]]=[steps[j],steps[i]];updateDecision(p,f,{steps});changed();render();},
 'link-decision':el=>{const d=decisionNodes(p).find(d=>d.id===el.dataset.owner),key=el.dataset.link;const values=el.checked?[...new Set([...(d[key]||[]),el.value])]:(d[key]||[]).filter(id=>id!==el.value);const patch={[key]:values};if(['screenIds','assetIds','flowIds'].includes(key))patch.scopeMode='targets';updateDecision(p,d,patch);changed();const select=('[data-decision]').find(e=>e.dataset.decision===d.id&&e.dataset.prop==='scopeMode');if(select&&patch.scopeMode)select.value=patch.scopeMode;},
 'unlink-dependency':el=>{const d=decisionNodes(p).find(d=>d.id===el.dataset.owner);updateDecision(p,d,{dependsOn:(d.dependsOn||[]).filter(id=>id!==el.dataset.id)});changed();render();},
 'output-target':el=>{const s=p.output.selection;s.ids=el.checked?[...new Set([...s.ids,el.value])]:s.ids.filter(id=>id!==el.value);p.output.scope=s.ids.map(id=>nodeName(p,id)).join(' / ')||'선택 대상 없음';touch(p,'이번 출력의 실제 대상 변경');changed();render();},
 'download-file':el=>{const f=files.find(f=>f.id===el.dataset.id);return downloadAPI('/projects/'+p.id+'/files/'+f.id+'?download=1',f.name);},
 'close-modal':()=>closeModal(),render:()=>render(),
 home:async()=>{await flush();settings.lastProject=null;await api('/settings','PUT',settings);p=null;projects=await api('/projects');renderTop();},
 create:el=>createModal(el.dataset.entry),
 'entry-select':el=>{creationEntry=el.dataset.entry;$$('.modal .entry-card').forEach(x=>x.classList.toggle('selected',x.dataset.entry===creationEntry));$('#create-submit').textContent=ENTRIES.find(x=>x[0]===creationEntry)[4]+' →';},
 'create-submit':async()=>{const name=$('#new-name').value.trim(),idea=$('#new-idea').value.trim();if(!name){$('#new-name').classList.add('invalid');$('#new-name').focus();throw new Error('프로젝트 이름을 적어 주세요. 설명은 아직 몰라도 됩니다.');}await flush();const project=newProject({name,idea,entry:creationEntry});if(settings.common)project.output.common=settings.common;project.settings.density='guide';await api('/projects','POST',project);closeModal();projects=await api('/projects');await openProject(project.id);renderTop();toast(ENTRIES.find(x=>x[0]===creationEntry)[4]);},
 sample:async el=>{await flush();const project=makeSample(el.dataset.kind);await api('/projects','POST',project);projects=await api('/projects');await openProject(project.id);renderTop();toast('가상 예시 프로젝트입니다. 제안 내용을 확인해 확정하세요.');},
 open:el=>openProject(el.dataset.id).then(()=>{closeModal();renderTop();}),
 switch:()=>showModal('Your projects',`<p>프로젝트마다 파일·선택·출력을 따로 보관합니다.</p><div class="project-list">${projects.map(x=>`<button class="project-row" data-action="open" data-id="${x.id}"><div><h3>${esc(x.name)}</h3><p>${esc(x.type)}</p></div><span></span><span></span><span>↗</span></button>`).join('')}</div><div class="modal-actions">${btn('+ 새 프로젝트','create','primary','data-entry="idea"')}</div>`,{wide:true}),
 tab:el=>navigate(el.dataset.tab),
 remedy:el=>navigate(el.dataset.tab,el.dataset.id,{remedy:true}),
 locate:el=>navigate(el.dataset.tab,el.dataset.id),
 return:async()=>{const back=p.progress.returnTo;p.progress.returnTo=null;if(back){p.progress.guideStage=back.guideStage;await navigate(back.tab);}},
 'navigate-next':()=>{const n=projectNext();if(n.stage!==undefined)ensureEasy(p).designStage=n.stage;return navigate(n.tab,n.id);},
 'mobile-menu':()=>$('.layout').classList.toggle('menu-open'),
 density:el=>{p.settings.density=el.dataset.value;changed();render();},
 'guide-stage':el=>{p.progress.guideStage=Number(el.dataset.value);changed();render();},
 'guide-next':()=>{if(p.progress.guideStage<3){p.progress.guideStage++;changed();renderTop();}else{document.querySelector('.section-title')?.scrollIntoView();toast('아래 기능과 콘텐츠 목록을 이어서 작성하세요.');}},
 type:el=>{if(p.type===el.dataset.value)return;p.type=el.dataset.value;touch(p,'제품 유형 변경');p.flows.filter(confirmed).forEach(x=>x.reviewNeeded=true);changed();render();},
 'edit-idea':()=>singleTextModal('Your original thought','처음의 아이디어 원문',p.idea,'save-idea'),
 'save-idea':()=>{p.idea=$('#modal-text').value;touch(p,'입력 원문 수정');changed();closeModal();render();},
 'use-original':()=>{updateDecision(p,p.fields.product,{value:p.idea,source:'user',status:'proposed'},'product');changed();render();locate('product');toast('원문을 그대로 연결했습니다. 확정 전에 직접 확인해 주세요.');},
 example:el=>{const q=QUESTIONS.find(q=>q.key===el.dataset.key),value=(EXAMPLES[p.type]||EXAMPLES['아직 미정'])[q.key];showModal('A place to start',`<p>${q.label}<br>${q.why}</p><div class="learning-note"><span class="tag proposed">내장 예시 · 이미지/원문 자동 분석 아님</span><p style="margin:12px 0 0">${esc(value)}</p></div><div class="modal-actions">${btn('원래 답 유지','close-modal','ghost')}${btn('이 예시를 제안으로 가져와 편집','use-example','primary',`data-key="${q.key}"`)}</div>`);},
 unknown:el=>actions.example(el),
 'use-example':el=>{exampleInto(p,el.dataset.key);changed();closeModal();render();locate(el.dataset.key);toast('제안으로 복제했습니다. 직접 수정하고 상태를 확정해 주세요.');},
 'review-decision':el=>{const d=allDecisions(p).find(x=>x.id===el.dataset.id);updateDecision(p,d,{reviewNeeded:false},undefined,{propagate:false});changed();render();},
 'add-feature':()=>{p.features.push(decision('','user','unknown',{priority:'이번 범위',purpose:'',action:'',info:'',flowIds:[]}));touch(p,'기능 추가');changed();render();},
 'feature-example':()=>{p.features.push(decision(p.type==='게임'?'탐험·채집·제작·건설':'입력·선택·편집·저장','example','proposed',{priority:'이번 범위',purpose:p.fields.goal.value||'사용자의 전체 목표',action:'필요한 작업을 수행하고 결과 확인',info:'작업 대상과 현재 상태',flowIds:p.flows.map(f=>f.id)}));touch(p,'기능 예시 복제');changed();render();},
 'add-content':()=>{p.contents.push(decision('','user','unknown',{kind:'문구',purpose:'',availability:'제작 필요',content:'',conditions:'',materialType:'제안 문구',screenIds:[],fileId:null}));touch(p,'콘텐츠 계획 추가');changed();render();},
 'flow-example':()=>{addFlowExample(p);changed();render();toast('예시를 복제했습니다. 화면 역할과 복구 정책을 직접 확인하세요.');},
 'add-flow':()=>{p.flows.push(decision('새 흐름','user','unknown',{goal:p.fields.goal.value,role:p.fields.user.value,start:'',steps:[],branch:'',recovery:'',complete:'',loop:false}));touch(p,'흐름 추가');changed();render();},
 'add-screen':()=>{p.screens.push(decision('새 화면','user','unknown',{kind:'페이지',role:'',entry:'',priority:'',actions:'',response:'',next:'',exceptions:'',preserve:'',links:[]}));touch(p,'화면·상태 추가');changed();render();},
 'flow-screen':el=>{const f=p.flows.find(f=>f.id===el.dataset.id);const steps=el.checked?[...f.steps,el.value]:f.steps.filter(id=>id!==el.value);updateDecision(p,f,{steps,reviewNeeded:true});if(f.graph){f.graph.version++;}changed();render();},
 'feature-link':el=>{const f=p.features.find(f=>f.id===el.dataset.id);f.flowIds=el.checked?[...(f.flowIds||[]),el.value]:f.flowIds.filter(id=>id!==el.value);f.version++;touch(p,'기능과 흐름 연결',[f.id]);changed();},
 'resource-screen':el=>{const d=allDecisions(p).find(d=>d.id===el.dataset.id);d.screenIds=el.checked?[...(d.screenIds||[]),el.value]:(d.screenIds||[]).filter(id=>id!==el.value);d.version++;touch(p,'자료와 화면 연결',[d.id]);changed();},
 'resource-reference':el=>{const d=allDecisions(p).find(d=>d.id===el.dataset.id);d.referenceIds=el.checked?[...(d.referenceIds||[]),el.value]:(d.referenceIds||[]).filter(id=>id!==el.value);d.version++;touch(p,'자료와 레퍼런스 연결',[d.id]);changed();},
 'upload-reference':()=>chooseFile(f=>addReference(f)),
 'replace-reference':el=>chooseFile(f=>addReference(f,el.dataset.id)),
 'add-reference-url':()=>{showModal('Keep the source',`<p>출처를 보관합니다. 실제 이미지가 없으면 관찰이나 분석 완료로 표시하지 않습니다.</p><label class="small-label">자료 이름</label><input class="input" id="ref-name"><label class="small-label">출처 URL</label><input class="input" id="ref-url" placeholder="https://…"><label class="small-label">취향 메모</label><textarea class="input" id="ref-note"></textarea><div class="modal-actions">${btn('출처만 저장하기','save-reference-url','primary')}</div>`);},
 'save-reference-url':()=>{const name=$('#ref-name').value.trim();if(!name)throw new Error('자료 이름을 적어 주세요.');const url=$('#ref-url').value.trim();if(url&&!/^https?:\/\//.test(url))throw new Error('출처 URL은 http:// 또는 https://로 적어 주세요.');const r={id:uid('ref'),name,url,note:$('#ref-note').value,role:'좋아하는 전체 느낌',fileId:null,regions:[]};p.references.push(r);activeRef=r.id;touch(p,'레퍼런스 출처 URL 등록');changed();closeModal();render();},
 'whole-region':el=>createRegion(p.references.find(x=>x.id===el.dataset.id),{x:0,y:0,w:1,h:1}),
 'recrop-region':el=>{const r=p.references.find(x=>x.id===el.dataset.ref),a=r.regions.find(x=>x.id===el.dataset.id);return createRegion(r,a.rect,a.id);},
 'observation-help':el=>showModal('Describe what you see',`<p>다음은 관찰을 돕는 일반 문장입니다. 현재 이미지에서 자동으로 찾은 특징이 아닙니다. 실제로 보이는 내용만 골라 수정하세요.</p>${['넓은 연한 바탕과 작은 강한 포인트가 대비된다.','얇은 선과 큰 여백이 반복된다.','매끈한 표면과 작은 입체 장식이 대비된다.','큰 제목과 짧은 보조 문장이 왼쪽으로 정렬되어 있다.'].map(t=>`<button class="item" style="display:block;width:100%;text-align:left;font-size:12px" data-action="observation-example" data-id="${el.dataset.id}" data-value="${t}">${t}</button>`).join('')}`),
 'observation-example':el=>{const d=allDecisions(p).find(d=>d.id===el.dataset.id);updateDecision(p,d,{value:el.dataset.value,observation:el.dataset.value,source:'example',status:'proposed'},'reference');changed();closeModal();render();toast('내장 문장을 제안으로 가져왔습니다. 실제 원본과 비교해 주세요.');},
 'sync-observation':el=>{const d=allDecisions(p).find(d=>d.id===el.dataset.id);updateDecision(p,d,{value:d.observation},'reference');changed();render();},
 'add-concept':()=>{const c=decision('','user','unknown',{selected:false,summary:p.entry==='concept'?p.idea:'',experience:p.fields.goal.value,hero:'',bg:'#f3f2ee',text:'#30342e',accent:'#516b50',font:'sans-serif',shape:'8px',typography:'',material:'',layout:'',intensity:'',resources:'',reference:'',assumptions:''});p.concepts.push(c);touch(p,'컨셉 직접 작성');changed();render();setTimeout(()=>locate(c.id),50);},
 'concept-examples':()=>{addConcepts(p);changed();render();},
 'choose-concept':el=>{const c=p.concepts.find(x=>x.id===el.dataset.id);if(!c.value.trim()||!c.summary.trim())throw new Error('컨셉 이름과 핵심 문장을 먼저 적어 주세요.');chooseConcept(p,c.id);changed();render();toast('이 방향을 선택했습니다. 탭은 이동하지 않았습니다. 색과 서체를 이어서 비교할 수 있습니다.');},
 'mix-concept':el=>{const c=p.concepts.find(x=>x.id===el.dataset.id);const others=p.concepts.filter(x=>x.id!==c.id);showModal('Make a new combination',`<p>이 방향의 주인공·구성을 유지하고, 다른 방향의 팔레트·재질을 가져오는 조합입니다. 복제 후 모든 항목을 직접 수정하고 새 샘플을 확인해 선택하세요.</p><label class="small-label">주인공·구성 기준</label><p>${esc(c.value)}</p><label class="small-label">색·재질을 가져올 방향</label><select class="input" id="mix-other">${others.map(o=>`<option value="${o.id}">${esc(o.value)}</option>`).join('')}</select><div class="modal-actions">${btn('조합을 제안으로 만들기','mix-submit','primary',`data-id="${c.id}"`)}</div>`);},
 'mix-submit':el=>{const c=p.concepts.find(x=>x.id===el.dataset.id),o=p.concepts.find(x=>x.id===$('#mix-other').value);if(!o)throw new Error('비교할 다른 방향을 먼저 등록하세요.');const n={...clone(c),id:uid(),version:1,history:[],status:'proposed',source:'user',selected:false,value:c.value+' + '+o.value,bg:o.bg,text:o.text,accent:o.accent,material:o.material,reason:'직접 조합. 주인공·구성은 '+c.value+', 색·재질은 '+o.value};p.concepts.push(n);touch(p,'컨셉 일부 요소 조합',[n.id]);changed();closeModal();render();},
 'concept-neither':()=>singleTextModal('Keep exploring','어떤 점이 의도와 다른가요?',p.conceptRejection||'','save-concept-rejection'),
 'save-concept-rejection':()=>{p.conceptRejection=$('#modal-text').value;p.concepts.forEach(c=>c.selected=false);touch(p,'컨셉 재탐색 이유 기록');changed();closeModal();render();},
 palette:el=>{const a=PALETTES[Number(el.dataset.index)];showModal('Compare the relationship',`${preview(a)}<p style="margin-top:17px">배경·본문·강조, 서체·형태·배치·재질·모션을 제안으로 추가합니다. 기존 확정 규칙은 보존되며 같은 역할과 범위의 값이 충돌하면 브리프에서 알려 줍니다.</p><div class="modal-actions">${btn('다른 조합 보기','close-modal','ghost')}${btn('이 조합을 규칙 후보로 가져오기','palette-submit','primary',`data-index="${el.dataset.index}"`)}</div>`);},
 'palette-submit':el=>{applyPalette(p,PALETTES[Number(el.dataset.index)]);changed();closeModal();render();},
 'concept-styles':()=>{const c=p.concepts.find(c=>c.selected)||p.concepts[0];if(c){applyPalette(p,c);changed();render();}},
 'add-style':()=>{p.styles.push(decision('','user','unknown',{role:'기타',scope:'',exception:''}));touch(p,'스타일 규칙 추가');changed();render();},
 'add-asset':()=>{p.assets.push(decision('','user','unknown',{kind:'',purpose:'',method:'직접 제작',availability:'제작 필요',rules:'',sourceUrl:'',usage:'',review:'',fileId:null,referenceIds:[]}));touch(p,'리소스 계획 추가');changed();render();},
 'confirm-intent':()=>{const reason=$('#intent-reason').value.trim();if(!reason)throw new Error('직접 확인한 이유를 한 문장 적어 주세요.');const list=issues(p,new Set(files.filter(f=>f.exists).map(f=>f.id)));if(list.length){toast(`먼저 보완할 항목 ${list.length}개가 있습니다. 초안은 만들 수 있습니다.`,true);$('.issue')?.scrollIntoView({block:'center'});return;}p.intent={choice:'match',reason,revision:p.revision,at:new Date().toISOString()};changed();render();toast('현재 기준의 의도를 확인했습니다. 실제 결과 검토는 이후에 진행합니다.');},
 'intent-edit':()=>navigate('design',undefined,{remedy:true}),
 'intent-rethink':()=>navigate('concept',undefined,{remedy:true}),
 assemble:async()=>{const list=issues(p,new Set(files.filter(f=>f.exists).map(f=>f.id)));if(list.length||!ready(p)){await navigate('brief');toast('확정 결정과 생성 전 사용자 확인을 보완해 주세요.',true);return;}const s=makeSnapshot(p);activeSnapshot=s.id;changed();await flush();render();toast('새 통합 프롬프트 버전을 보관했습니다.');},
 'assemble-draft':async()=>{const s=makeSnapshot(p,{draft:true});activeSnapshot=s.id;changed();await flush();render();},
 copy:async el=>{const s=p.snapshots.find(s=>s.id===el.dataset.id);try{await navigator.clipboard.writeText(s.text);toast('전체 프롬프트를 복사했습니다. 참고 파일도 함께 첨부하세요.');}catch{showModal('Copy your prompt',`<p>아래 문서를 선택해 Ctrl+C로 복사하세요.</p><textarea class="input" style="height:350px" id="copy-fallback" readonly>${esc(s.text)}</textarea>`);$('#copy-fallback').select();}},
 markdown:el=>{const s=p.snapshots.find(s=>s.id===el.dataset.id);download(p.name+'-v'+s.number+'.md',s.text,'text/markdown');},
 bundle:el=>downloadAPI('/projects/'+p.id+'/bundle?snapshot='+el.dataset.id,p.name+'-자료묶음.zip'),
 trace:el=>{const s=p.snapshots.find(s=>s.id===el.dataset.id);showModal('Follow each decision',`<p>각 문단은 생성 당시 결정 ID와 버전에 연결됩니다. 아래 버튼은 현재 편집 위치로 이동합니다. 당시 원문은 스냅샷에 보존됩니다.</p>${s.sections.map(section=>`<article class="prompt-section"><h3>${esc(section.title)}</h3><p>${esc(section.body.slice(0,850))}${section.body.length>850?'…':''}</p><div class="trace-list">${section.decisionIds.map(id=>`<button data-action="trace-locate" data-tab="${section.tab}" data-id="${id}">${id.slice(0,14)}… @${s.decisions.find(d=>d.id===id)?.version||'기준'}</button>`).join('')||'<small>버전 있는 템플릿 문장 또는 출력 설정</small>'}</div></article>`).join('')}`,{wide:true});},
 'trace-locate':async el=>{closeModal();const q=QUESTIONS.find(q=>p.fields[q.key].id===el.dataset.id);return navigate(el.dataset.tab,q?.key||el.dataset.id);},
 'mark-handoff':async el=>{p.handoff={snapshotId:el.dataset.id,waiting:true,revision:!!p.snapshots.find(s=>s.id===el.dataset.id)?.planId,at:new Date().toISOString()};changed();await flush();render();toast('사용자가 전달한 버전으로 기록했습니다. 외부 제작 상태는 조회하지 않습니다.');},
 'result-from-snapshot':el=>resultModal(el.dataset.id),
 'register-result':()=>resultModal(),
 baseline:()=>baselineModal(),
 'baseline-submit':async()=>{const s=baseline(p,$('#modal-text').value);activeSnapshot=s.id;changed();await flush();closeModal();render();resultModal(s.id);},
 'result-submit':async()=>{const file=$('#result-file').files[0],execution=$('#result-execution').value.trim(),screen=$('#result-screen').value.trim(),source=$('#result-source').value.trim();if(!file&&!execution)throw new Error('실제 결과 이미지 또는 직접 확인한 실행 기록이 필요합니다.');if(!screen||!source)throw new Error('화면 이름과 실제 출처를 적어 주세요.');const data={snapshotId:$('#result-snapshot').value,screen,source,execution,environment:$('#result-environment').value,instruction:$('#result-instruction').value,note:$('#result-note').value,keep:$('#result-keep').value};const f=file?await upload(file):null;const result={id:uid('result'),number:p.results.length+1,createdAt:new Date().toISOString(),fileId:f?.id||null,...data};p.results.push(result);const r=beginReview(p,result);activeReview=r.id;p.progress.tab='review';changed();await flush();closeModal();renderTop();toast('당시 기준을 고정하고 실제 결과에 연결했습니다. 직접 판정해 주세요.');},
 verdict:el=>{const r=p.reviews.find(x=>x.id===el.dataset.review),item=r.items[Number(el.dataset.index)];item.verdict=el.dataset.value;if(r.state==='completed')r.state='reviewing';changed();render();},
 'review-intent':el=>{const r=p.reviews.find(x=>x.id===el.dataset.id);r.intent=el.dataset.value;if(r.state==='completed')r.state='reviewing';changed();render();},
 plan:el=>planModal(p.reviews.find(x=>x.id===el.dataset.id)),
 'resume-plan':()=>{const draft=p.progress.planDraft;if(!draft)return;planModal(p.reviews.find(x=>x.id===draft.reviewId),{...draft.form,id:null});},
 'edit-plan':el=>{const plan=p.plans.find(x=>x.id===el.dataset.id);planModal(p.reviews.find(x=>x.id===plan.reviewId),plan);},
 'plan-submit':el=>{const f=Object.fromEntries(['problem','cause','target','change','scope','keep','materials','check'].map(k=>[k,$('#plan-'+k).value.trim()]));if(el.dataset.id){if(!f.change||!f.keep||!f.check)throw new Error('변경 목표·유지할 조건·재검토 기준이 필요합니다.');Object.assign(p.plans.find(x=>x.id===el.dataset.id),f,{confirmed:false});}else createPlan(p,p.reviews.find(x=>x.id===el.dataset.review),f);p.progress.planDraft=null;changed();closeModal();render();toast('수정 계획을 저장했습니다. 아직 해결된 것은 아닙니다.');},
 'plan-remedy':async el=>{const form=Object.fromEntries(['problem','cause','target','change','scope','keep','materials','check'].map(k=>[k,$('#plan-'+k).value]));p.progress.planDraft={form,reviewId:activeReview};closeModal();await navigate(el.dataset.tab,undefined,{remedy:true});toast('수정 계획 임시 입력을 유지했습니다. 돌아와 “저장한 수정 계획 이어쓰기”를 선택하세요.');},
 'revision-prompt':async el=>{const plan=p.plans.find(x=>x.id===el.dataset.id);plan.confirmed=true;const s=makeSnapshot(p,{plan});activeSnapshot=s.id;p.handoff={snapshotId:s.id,waiting:true,revision:true,at:new Date().toISOString()};p.progress.tab='prompt';changed();await flush();renderTop();toast('전체 맥락과 수정·유지·재검토 기준을 담은 새 버전입니다.');},
 'complete-review':async el=>{const r=p.reviews.find(x=>x.id===el.dataset.id);finishReview(p,r);changed();await flush();render();toast(r.scope==='visual'?'등록한 화면의 시각 검토 범위를 확인했습니다. 동작 확인은 별도입니다.':'실행 근거가 있는 해당 검토 범위를 확인했습니다.');},
 'hold-review':el=>{singleTextModal('Leave a note, come back later','미해결 항목을 보류하는 이유','','hold-submit');$('.modal').dataset.review=el.dataset.id;},
 'hold-submit':()=>{const r=p.reviews.find(x=>x.id===$('.modal').dataset.review),reason=$('#modal-text').value.trim();if(!reason)throw new Error('보류 이유를 적어 주세요.');r.holdReason=reason;r.state='held';changed();closeModal();render();},
 'learning-export':el=>{const r=p.reviews.find(x=>x.id===el.dataset.id);download(p.name+'-학습기록.md',`# ${p.name} — 학습 기록\n\n기준 ${r.snapshotId}; 실제 결과 ${r.resultId}; 상태 ${r.state}; 범위 ${r.scope}\n\n`+r.items.map(i=>`## ${i.label}\n기대: ${i.expected}\n관찰: ${i.observation}\n근거: ${i.evidence}\n판정: ${i.verdict}\n변경: ${i.target}\n유지: ${i.keep}\n재검토: ${i.resolution}`).join('\n\n')+'\n\n배운 점: '+r.learning,'text/markdown');},
 'reuse-learning':el=>{const r=p.reviews.find(x=>x.id===el.dataset.id);singleTextModal('A principle to keep','다른 작업에서도 재사용할 원칙을 직접 확인하세요',r.learning,'reuse-submit',{help:'일회성 취향을 자동으로 공통 규칙으로 바꾸지 않습니다. 직접 선택한 문장만 기준 후보로 추가합니다.'});},
 'reuse-submit':()=>{const text=$('#modal-text').value.trim();if(!text)throw new Error('재사용할 원칙을 적어 주세요.');p.output.common+='\n사용자 재사용 원칙: '+text;p.output.commonVersion++;touch(p,'학습 원칙을 공통 기준 후보로 선택');changed();closeModal();render();},
 backup:async()=>{await downloadAPI('/projects/'+p.id+'/backup',p.name+'.atelier.json');toast('데이터·원본·크롭·결과 파일을 함께 백업했습니다.');},
 restore:()=>{showModal('Bring your workspace back',`<p>자체 JSON 백업의 형식·버전·해시·파일 참조를 확인합니다. 복원은 새 프로젝트로 만들며 현재 프로젝트를 덮어쓰지 않습니다.</p><input class="input" type="file" accept=".json,application/json" id="restore-file"><div class="modal-actions">${btn('취소','close-modal','ghost')}${btn('파일을 확인하고 새 프로젝트로 복원','restore-submit','primary')}</div>`);},
 'restore-submit':async()=>{const f=$('#restore-file').files[0];if(!f)throw new Error('Atelier JSON 백업을 선택하세요.');if(f.size>90*1024*1024)throw new Error('백업은 90MB 이하여야 합니다.');let b;try{b=JSON.parse(await f.text());}catch{throw new Error('JSON을 읽을 수 없습니다. 기존 입력과 확정 결정은 보존되었습니다.');}await flush();const restored=await api('/restore','POST',b);closeModal();projects=await api('/projects');await openProject(restored.id);renderTop();toast('원본 파일과 참조 관계를 새 프로젝트로 복원했습니다.');},
 settings:()=>settingsModal(),
 'settings-close':async()=>{await flush();closeModal();render();},
 'save-common':async()=>{settings.common=p.output.common;settings.density=p.settings.density;settings.commonVersion=p.output.commonVersion;await api('/settings','PUT',settings);toast('직접 선택한 공통 기준을 새 프로젝트의 기본값으로 저장했습니다.');},
 'save-global-common':async()=>{settings.common=$('#global-common').value;await api('/settings','PUT',settings);closeModal();toast('새 프로젝트 기본 작업 기준을 저장했습니다.');},
 'delete-project':()=>showModal('Delete this project?',`<p><strong>${esc(p.name)}</strong> 프로젝트와 데이터, 원본·크롭·결과 이미지 ${files.length}개, 프롬프트 ${p.snapshots.length}개를 이 컴퓨터에서 삭제합니다. 먼저 백업하면 복원할 수 있습니다.</p><div class="modal-actions">${btn('취소','close-modal','ghost')}${btn('데이터와 파일 백업','backup','tiny')}${btn('이 프로젝트와 파일 삭제','delete-confirm','danger')}</div>`),
 'delete-confirm':async()=>{await flush();const id=p.id;await api('/projects/'+id,'DELETE',{});localStorage.removeItem('atelier-draft-'+id);p=null;dirty=saved=0;settings.lastProject=null;await api('/settings','PUT',settings);projects=await api('/projects');closeModal();renderTop();toast('선택한 프로젝트와 연결 파일을 삭제했습니다.');},
 'retry-save':async()=>{await flush();render();toast('입력을 다시 저장했습니다.');},
 'reload-latest':()=>showModal('Open the saved version',`<p>현재 임시 입력은 브라우저에 보존합니다. 최신 서버 저장본을 읽어 현재 편집 화면을 바꿉니다. 입력을 비교하려면 먼저 임시 입력을 내려받으세요.</p><div class="modal-actions">${btn('현재 임시 입력 내려받기','draft-download','tiny')}${btn('최신 저장본을 읽고 비교하기','reload-confirm','primary')}</div>`),
 'reload-confirm':async()=>{const id=p.id;p=await api('/projects/'+id);dirty=saved=0;saveError='';await refreshFiles();closeModal();renderTop();toast('최신 저장본을 열었습니다. 이전 임시 입력은 설정에서 내려받을 수 있습니다.');},
 'draft-download':()=>{const raw=localStorage.getItem('atelier-draft-'+p.id)||JSON.stringify(p);download(p.name+'-임시입력.json',raw,'application/json');toast('이미지 없는 임시 입력입니다. 전체 복원에는 “데이터와 원본 백업”을 사용하세요.');},
 'recover-draft':async()=>{p=JSON.parse(localStorage.getItem('atelier-draft-'+p.id));dirty++;await flush();closeModal();render();toast('임시 입력을 복구했습니다.');},
 'discard-draft':()=>{localStorage.removeItem('atelier-draft-'+p.id);closeModal();},
 help:()=>showModal('A little guide',`<p>01. 아이디어·이미지·정한 컨셉·기존 결과 중 지금 가진 것부터 시작합니다.</p><p>02. 내장 예시는 제안입니다. 직접 수정하고 확인한 항목만 확정하세요. 아직 모르면 비교 예시를 볼 수 있습니다.</p><p>03. 여덟 탭은 같은 데이터를 씁니다. 가이드의 다음 행동을 따르거나 자유롭게 이동할 수 있습니다.</p><p>04. 브리프에서 필수 정보와 내 의도를 확인한 뒤 프롬프트와 자료 묶음을 내보냅니다.</p><p>05. 외부에서 제작한 실제 결과를 등록해 당시 기준과 비교합니다. 차이를 수정 계획으로 만들고 새 결과를 같은 기준으로 다시 확인합니다.</p><p>화면에 저장됨이 표시되어도 요구가 확정되거나 실제 결과 검토가 완료된 것은 아닙니다.</p><div class="modal-actions">${btn('내 작업으로 돌아가기','close-modal','primary')}</div>`),
 'retry-start':()=>init()
};

function commitGraphControl(el){if(!p)return;const f=p.flows.find(f=>f.id===el.dataset.graph);if(!f)return;const key=el.dataset.graphKey,current=el.dataset.edge?f.graph.transitions.find(e=>e.id===el.dataset.edge):f.graph;if(!current||current[key]===el.value)return;editGraph(p,f,g=>{const target=el.dataset.edge?g.transitions.find(e=>e.id===el.dataset.edge):g;target[key]=el.value;});changed();}
const fontLoads=new Map();
async function loadProjectFonts(){if(!p||typeof FontFace==='undefined')return;const projectId=p.id;const load=async fileId=>{const f=files.find(f=>f.id===fileId&&f.exists&&f.mime.startsWith('font/'));if(!f)throw new Error('서체 파일이 없습니다.');const cacheKey=projectId+':'+fileId+':'+f.sha256;const family='AtelierProject_'+(projectId+'_'+fileId+'_'+f.sha256.slice(0,12)).replaceAll('-','_');if(!fontLoads.has(cacheKey))fontLoads.set(cacheKey,(async()=>{const face=new FontFace(family,`url(${fileURL(fileId)})`);await face.load();document.fonts.add(face);return family;})());return fontLoads.get(cacheKey);};for(const el of $$('[data-font-file]')){try{const family=await load(el.dataset.fontFile);if(p?.id===projectId&&el.isConnected)el.style.fontFamily=`"${family}", var(--sans)`;}catch{if(el.isConnected)el.textContent='서체 파일을 미리 보지 못했습니다. 원본 파일과 사용 조건을 확인하세요.';}}const rule=p.styles.find(s=>s.role==='서체'&&confirmed(s)&&s.fontAssetId);if(!rule)return;const asset=p.assets.find(a=>a.id===rule.fontAssetId);try{const family=await load(asset?.fileId);if(p?.id===projectId&&currentTab()==='style')$('.style-sample')?.style.setProperty('--project-font',`"${family}", var(--sans)`);}catch{if(p?.id===projectId)toast('선택한 서체를 읽지 못했습니다. 리소스의 실제 파일을 확인하세요.',true);}}
function commitControl(el){if(!p)return;const prop=el.dataset.prop,path=el.dataset.path;let value=el.type==='checkbox'?el.checked:el.value;if(el.dataset.decision){const d=allDecisions(p).find(x=>x.id===el.dataset.decision);if(!d)return;const key=Object.keys(p.fields).find(k=>p.fields[k]===d)|| (p.concepts.includes(d)?'concept':null);const original=editStart.get(el);if(original&&el.tagName!=='SELECT'&&el.type!=='checkbox'){
 if(!original.started){updateDecision(p,d,{[prop]:value,...(prop==='observation'?{value}: {})},key);original.started=true;}
 d[prop]=value;if(prop==='observation')d.value=value;
 }else{updateDecision(p,d,{[prop]:value,...(prop==='observation'?{value}: {}),...(prop==='status'&&value==='confirmed'?{reviewNeeded:false}:{})},key);}
 if(d.history.length>50)d.history=d.history.slice(-50);
 }else if(path){const old=getPath(p,path);if(old===value)return;setPath(p,path,value);if(!/^(reviews|results|plans|settings|progress)\./.test(path)){if(path==='output.common')p.output.commonVersion++;p.output.version++;const root=path.startsWith('references.')?p.references[Number(path.split('.')[1])]?.id:null;touch(p,'작업 정보 변경',root?[root]:[]);}else if(path.startsWith('reviews.')){const r=p.reviews[Number(path.split('.')[1])];if(r.state==='completed')r.state='reviewing';}}
 changed();
}
async function handleEasyAction(el){if(el.dataset.action==='easy-start-review'){const wanted=$('#review-wanted').value.trim(),problem=$('#review-problem').value.trim();if(!wanted||!problem)throw new Error('기대한 화면과 바꾸고 싶은 점을 각각 한 문장 적어 주세요.');updateDecision(p,p.fields.goal,{value:wanted,status:'confirmed',source:'user'},'goal');const s=baseline(p,'사용자 기대: '+wanted+' / 바꾸고 싶은 점: '+problem);activeSnapshot=s.id;changed();await flush();render();resultModal(s.id);return;}if(el.dataset.action==='easy-review-step'){ensureEasy(p).reviewIndex=Number(el.dataset.index);changed();render();$('.review-item')?.scrollIntoView({block:'start'});return;}return handleEasy(p,el,{files,changed,render,locate,modal:showModal,close:closeModal});}
function reviewItems(r){if(p.settings.density==='quick')return r.items.map((item,i)=>reviewItem(r,item,i)).join('');const e=ensureEasy(p),i=Math.min(e.reviewIndex,r.items.length-1);return '<div class="easy-guide"><h2>한 번에 한 기준씩 실제 결과를 확인해요.</h2><p class="easy-intro">기대와 실제가 어떻게 다른지 적고 판정을 골라 주세요. 모르는 항목은 확인 불가로 남길 수 있어요.</p><div class="easy-review-tabs">'+r.items.map((item,j)=>'<button class="btn '+(i===j?'primary':'')+'" data-action="easy-review-step" data-index="'+j+'">'+(j+1)+'. '+esc(item.label)+'</button>').join('')+'</div>'+reviewItem(r,r.items[i],i)+'<div class="easy-footer">'+(i>0?'<button class="btn" data-action="easy-review-step" data-index="'+(i-1)+'">← 이전 기준</button>':'')+(i<r.items.length-1?'<button class="btn primary" data-action="easy-review-step" data-index="'+(i+1)+'">다음 기준 확인 →</button>':'<p>각 기준을 확인했다면 아래에서 전체 판단과 수정할 항목을 정하세요.</p>')+'</div></div>';}
document.addEventListener('focusin',e=>{const el=e.target;if(el.dataset.decision)editStart.set(el,{value:el.value,started:false});});
function updateEasySample(el){if(!p||p.settings.density==='quick'||currentTab()!=='style')return;const d=p.styles.find(s=>s.id===el.dataset.decision),sample=$('.easy-sample');if(!d||!sample)return;if(d.role==='배경')sample.style.background=d.value;if(d.role==='본문')sample.style.color=d.value;if(d.role==='강조')sample.querySelector('.easy-sample-button').style.background=d.value;if(d.role==='서체')sample.querySelector('h3').style.fontFamily=['serif','sans-serif','monospace'].includes(d.value)?d.value:'sans-serif';if(d.role==='형태')sample.style.borderRadius=d.value;const code=$('[data-color-rule="'+d.id+'"]');if(code)code.textContent=d.value;}
document.addEventListener('input',e=>{const el=e.target;if(el.hasAttribute('aria-invalid')){el.removeAttribute('aria-invalid');el.classList.remove('invalid');}if(el.id==='easy-concept-name'||el.id==='easy-concept-summary'){ensureEasy(p)[el.id==='easy-concept-name'?'conceptName':'conceptSummary']=el.value;changed();return;}if(el.dataset.graph&&el.tagName!=='SELECT')commitGraphControl(el);else if(el.dataset.decision||el.dataset.path){commitControl(el);updateEasySample(el);}});
document.addEventListener('change',async e=>{const el=e.target;try{
 if(el.dataset.upload&&el.files?.[0]){const type=el.dataset.upload;if(type==='reference'||type==='replace-reference')await addReference(el.files[0],type==='replace-reference'?el.dataset.id:null);else{const d=allDecisions(p).find(x=>x.id===el.dataset.id);const f=await upload(el.files[0],type);updateDecision(p,d,{fileId:f.id,availability:'보유'});changed();await flush();render();}return;}
 if(el.id==='output-scope-mode'){p.output.selection={mode:el.value,ids:[]};if(el.value==='all')p.output.purpose='서비스 전체 UI UX 설계';else p.output.purpose=el.value==='assets'?'리소스 제작 요청':'특정 흐름 또는 화면 설계';touch(p,'실제 출력 대상 단위 변경');changed();render();return;}
 if(el.dataset.addDependency){const d=decisionNodes(p).find(d=>d.id===el.dataset.addDependency);if(el.value)updateDecision(p,d,{dependsOn:[...new Set([...(d.dependsOn||[]),el.value])]});changed();render();return;}
 if(el.dataset.graph){commitGraphControl(el);if(el.tagName==='SELECT')render();return;}
 if(el.id==='ref-select'){activeRef=el.value;render();return;}if(el.id==='snapshot-select'){activeSnapshot=el.value;render();return;}if(el.id==='review-select'){activeReview=el.value;render();return;}
 if(el.dataset.action){if(el.dataset.action.startsWith('easy-'))await handleEasyAction(el);else await actions[el.dataset.action]?.(el);return;}
 if(el.tagName==='SELECT'||el.type==='checkbox'){commitControl(el);if(!el.closest('.modal'))render();}
 }catch(err){if(el.type==='file')el.value='';toast(err.message,true);}});
document.addEventListener('click',async e=>{const el=e.target.closest('[data-action]');if(!el||el.type==='checkbox')return;e.preventDefault();const action=actions[el.dataset.action]||(el.dataset.action.startsWith('easy-')?handleEasyAction:null);if(!action)return;const old=el.disabled;try{if(pendingFiles){toast('원본 프로젝트에 파일을 등록하는 중입니다. 완료 후 이동하거나 실행할 수 있습니다.');return;}el.disabled=true;await action(el);}catch(err){if(err.field){const field=document.getElementById(err.field);if(field){field.setAttribute('aria-invalid','true');field.classList.add('invalid');field.focus();}}toast(err.message||String(err),true);}finally{if(el.isConnected)el.disabled=old;}});
document.addEventListener('keydown',e=>{const modal=$('.modal');if(modal){if(e.key==='Escape'){closeModal();return;}if(e.key==='Tab'){const focusables=[...modal.querySelectorAll('button,a,input,textarea,select,summary')].filter(x=>!x.disabled&&x.getClientRects().length);if(e.shiftKey&&document.activeElement===focusables[0]){e.preventDefault();focusables.at(-1)?.focus();}else if(!e.shiftKey&&document.activeElement===focusables.at(-1)){e.preventDefault();focusables[0]?.focus();}}}else if(e.key==='Escape')$('.layout')?.classList.remove('menu-open');});
window.addEventListener('beforeunload',e=>{if(p&&(pendingFiles||dirty>saved)){e.preventDefault();e.returnValue='입력을 저장 중입니다.';}});
let scrollFrame=false;window.addEventListener('scroll',()=>{if(scrollFrame)return;scrollFrame=true;requestAnimationFrame(()=>{const total=document.documentElement.scrollHeight-innerHeight;$('.workspace-top')?.style.setProperty('--scroll',String(total>0?Math.min(1,scrollY/total):0));scrollFrame=false;});},{passive:true});
async function init(){try{[projects,settings]=await Promise.all([api('/projects'),api('/settings')]);if(settings.lastProject&&projects.some(x=>x.id===settings.lastProject))await openProject(settings.lastProject);else render();}catch(e){$('#app').innerHTML=`<main class="home" style="padding-top:100px"><div class="wordmark">atelier<span>.</span></div><h1 style="margin-top:30px;font-size:24px">작업실을 연결하지 못했습니다.</h1><p style="margin:20px 0;color:var(--muted)">로컬 서버가 실행 중인지 확인하세요. 기존 데이터와 임시 입력은 보존됩니다.</p><div class="error-note">${esc(e.message)}</div>${btn('로컬 서버에 다시 연결','retry-start','primary')}</main>`;}}
init();










